30	
31	// RunShow prints the saved investigation summary + findings for the
32	// requested run id. Resolution rules:
33	//   - empty RunID + exactly one manifest → use that manifest
34	//   - empty RunID + multiple manifests   → list candidates, return error
35	//   - non-empty RunID: exact match wins; otherwise unique-prefix match;
36	//     otherwise return an "ambiguous" or "not found" error
37	//
38	// Findings come from manifest.FindingsContent when present (terminal
39	// outcomes), or by reading manifest.FindingsDoc from disk (paused /
40	// cancelled runs whose per-run dir still exists). Both paths missing
41	// is a soft state — the header is printed with an explanatory line.
42	func RunShow(ctx context.Context, in ShowInput, deps ShowDeps) error {
43		if deps.ManifestStore == nil {
44			return errors.New("show: manifest store not wired")
45		}
46	
47		// Fast path: a full 12-hex run id resolves via Glob + one file read.
48		runID := strings.TrimSpace(in.RunID)
49		if IsValidRunID(runID) {
50			m, ok, err := deps.ManifestStore.FindByRunID(ctx, runID)
51			if err != nil {
52				return fmt.Errorf("find manifest %s: %w", runID, err)
53			}
54			if !ok {
55				return fmt.Errorf("no investigation found with run id %q", runID)
56			}
57			printShowSummary(in.Out, m)
58			printShowFindings(in.Out, m)
59			return nil
60		}
61	
62		manifests, err := deps.ManifestStore.List(ctx)
63		if err != nil {
64			return fmt.Errorf("list manifests: %w", err)
65		}
66		if len(manifests) == 0 {
67			fmt.Fprintln(in.Out, "No local investigations found.")
68			return nil
69		}
70	
71		if runID == "" {
72			if len(manifests) == 1 {
73				printShowSummary(in.Out, manifests[0])
74				printShowFindings(in.Out, manifests[0])
75				return nil
76			}
77			return ambiguousRunIDError(manifests, "")
78		}
79	
80		resolved, err := ResolveByRunID(manifests, runID)
81		if err != nil {
82			return err
83		}
84		printShowSummary(in.Out, resolved[0])
85		printShowFindings(in.Out, resolved[0])
86		return nil
87	}
88	
89	// printShowSummary writes the header block (prompt, agents, outcome,
90	// timestamps, stances per agent) to w. Keeps the format compact and
91	// stable so users can grep its output.
92	func printShowSummary(w io.Writer, m LocalManifest) {
93		fmt.Fprintf(w, "Investigation %s\n", m.RunID)
94		if m.Topic != "" {
95			fmt.Fprintf(w, "Prompt:   %s\n", m.Topic)
96		}
97		if len(m.Agents) > 0 {
98			fmt.Fprintf(w, "Agents:   %s\n", strings.Join(m.Agents, ", "))
99		}
100		if m.Outcome != "" {
101			fmt.Fprintf(w, "Outcome:  %s\n", m.Outcome)
102		}
103		if !m.StartedAt.IsZero() {
104			fmt.Fprintf(w, "Started:  %s\n", m.StartedAt.UTC().Format("2006-01-02 15:04:05Z"))
105		}
106		if !m.EndedAt.IsZero() {
107			fmt.Fprintf(w, "Ended:    %s\n", m.EndedAt.UTC().Format("2006-01-02 15:04:05Z"))
108		}
109		if len(m.StancesByAgent) > 0 {
110			keys := make([]string, 0, len(m.StancesByAgent))
111			for k := range m.StancesByAgent {
112				keys = append(keys, k)
113			}
114			sort.Strings(keys)
115			fmt.Fprintln(w)
116			fmt.Fprintln(w, "Last stance per agent:")
117			for _, k := range keys {
118				fmt.Fprintf(w, "  %s: %s\n", k, m.StancesByAgent[k])
119			}
120		}
121		fmt.Fprintln(w)
122	}
123	
124	// printShowFindings writes the findings content to w. Prefers the
125	// manifest's embedded content (set on terminal outcomes); falls back
126	// to reading the on-disk findings file (still present for paused or
127	// cancelled runs). Body is rendered through mdrender for terminal
128	// output; raw markdown passes through for piped/NO_COLOR output.
129	func printShowFindings(w io.Writer, m LocalManifest) {
130		body := ""
131		switch {
132		case m.FindingsContent != "":
133			body = m.FindingsContent
134		case m.FindingsDoc != "":
135			if data, err := os.ReadFile(m.FindingsDoc); err == nil {
136				body = string(data)
137			}
138		}
139		if body == "" {
140			fmt.Fprintf(w, "No findings content available for run %s.\n", m.RunID)
141			return
142		}
143		rendered, err := mdrender.RenderForWriter(w, body)
144		if err != nil {
145			// Glamour failure: fall back to raw markdown so the user still
146			// sees the content.
147			rendered = body
148		}
149		fmt.Fprint(w, rendered)
150		if !strings.HasSuffix(rendered, "\n") {
151			fmt.Fprintln(w)
152		}
153	}
