16	)
17	
18	const manifestsSubdirName = "manifests"
19	
20	// LocalManifest is the persisted record of one `entire investigate` run for
21	// local findings browsing. Written to <git-common-dir>/entire-investigations/
22	// manifests/<timestamp>-<run-id>.json after each run terminates.
23	//
24	// The schema is intentionally narrower than RunState: this file is what
25	// `entire investigate --findings` reads to render the picker, so it carries
26	// only what a human (or `entire status`) needs to identify a past run, not the
27	// state needed to resume one.
28	type LocalManifest struct {
29		// RunID is the 12-hex-char investigation run identifier.
30		RunID string `json:"run_id"`
31	
32		// Topic is the human-readable subject of the investigation.
33		Topic string `json:"topic"`
34	
35		// Slug is the filesystem-safe form of Topic, derived via SlugifyTopic.
36		Slug string `json:"slug"`
37	
38		// StartingSHA is the git commit SHA that was HEAD when the
39		// investigation started.
40		StartingSHA string `json:"starting_sha"`
41	
42		// WorktreePath is the absolute path to the worktree the run executed
43		// in. Empty when the run was not associated with a specific
44		// worktree.
45		WorktreePath string `json:"worktree_path,omitempty"`
46	
47		// FindingsDoc is the absolute path to the findings document the run
48		// produced. May also be a repo-relative path when the caller chose
49		// to record it that way. The on-disk file is removed for terminal
50		// outcomes (Quorum/Stalled) once FindingsContent has been captured —
51		// the path remains here for resumable runs (Paused/Cancelled) where
52		// the file still lives in the per-run directory.
53		FindingsDoc string `json:"findings_doc,omitempty"`
54	
55		// FindingsContent embeds the final findings.md content as of run
56		// end. Populated on terminal outcomes (Quorum/Stalled) so the
57		// findings survive after the per-run directory is cleaned up. Empty
58		// on Paused/Cancelled — those runs are resumable and the file lives
59		// on disk in the per-run directory at FindingsDoc.
60		FindingsContent string `json:"findings_content,omitempty"`
61	
62		// Agents is the ordered list of agent names that participated in
63		// the run.
64		Agents []string `json:"agents"`
65	
66		// Outcome is the terminal outcome of the run. One of: "quorum",
67		// "stalled", "paused", "cancelled".
68		Outcome string `json:"outcome"`
69	
70		// StancesByAgent records the LAST stance each agent expressed in
71		// the run, keyed by agent name. Empty when the run terminated
72		// without any stances being recorded.
73		StancesByAgent map[string]string `json:"stances_by_agent,omitempty"`
74	
75		// StartedAt is when the run was initiated.
76		StartedAt time.Time `json:"started_at"`
77	
