79		EndedAt time.Time `json:"ended_at"`
80	}
81	
82	// LocalManifestStore wraps the directory that holds persisted LocalManifest
83	// JSON files for one repository.
84	type LocalManifestStore struct {
85		dir string
86	}
87	
88	// NewLocalManifestStore creates a LocalManifestStore rooted at
89	// <git-common-dir>/entire-investigations/manifests. Resolves the common dir
90	// via session.GetGitCommonDir, so this requires a git repository context.
91	func NewLocalManifestStore(ctx context.Context) (*LocalManifestStore, error) {
92		commonDir, err := session.GetGitCommonDir(ctx)
93		if err != nil {
94			return nil, fmt.Errorf("get git common dir: %w", err)
95		}
96		return &LocalManifestStore{
97			dir: filepath.Join(commonDir, InvestigationsDirName, manifestsSubdirName),
98		}, nil
99	}
100	
101	// NewLocalManifestStoreWithDir creates a LocalManifestStore rooted at dir.
102	// Useful for tests that do not want to depend on a real git repository.
103	func NewLocalManifestStoreWithDir(dir string) *LocalManifestStore {
104		return &LocalManifestStore{dir: dir}
105	}
106	
107	// Write persists m to the manifests directory using a deterministic filename
108	// derived from m.StartedAt and m.RunID. Existing files are overwritten — the
109	// timestamp+run-id combination is unique by construction (each run has a fresh
110	// run ID and a different start time).
111	func (s *LocalManifestStore) Write(ctx context.Context, m LocalManifest) error {
112		_ = ctx // Reserved for future use.
113	
114		if err := validateRunID(m.RunID); err != nil {
115			return fmt.Errorf("invalid run ID: %w", err)
116		}
117		if m.StartedAt.IsZero() {
118			return errors.New("manifest StartedAt is required")
119		}
120	
121		if err := os.MkdirAll(s.dir, 0o750); err != nil {
122			return fmt.Errorf("create investigations manifests dir: %w", err)
123		}
124	
125		data, err := jsonutil.MarshalIndentWithNewline(m, "", "  ")
126		if err != nil {
127			return fmt.Errorf("marshal manifest: %w", err)
128		}
129	
130		finalPath := filepath.Join(s.dir, manifestFilename(m))
131		if err := jsonutil.WriteFileAtomic(finalPath, data, 0o644); err != nil {
132			return fmt.Errorf("write manifest: %w", err)
133		}
134		return nil
135	}
136	
137	// List returns every manifest in the store sorted newest first by StartedAt.
138	// A missing directory is treated as an empty list (nil, nil) — useful for
139	// callers that want to render `--findings` even when no investigation has
140	// ever been run in this repo.
141	func (s *LocalManifestStore) List(ctx context.Context) ([]LocalManifest, error) {
142		_ = ctx // Reserved for future use.
143	
144		entries, err := os.ReadDir(s.dir)
145		if err != nil {
146			if errors.Is(err, os.ErrNotExist) {
147				return nil, nil
148			}
149			return nil, fmt.Errorf("read investigations manifests dir: %w", err)
150		}
151	
152		manifests := make([]LocalManifest, 0, len(entries))
153		for _, entry := range entries {
154			if entry.IsDir() {
155				continue
156			}
157			name := entry.Name()
158			if !strings.HasSuffix(name, ".json") || strings.HasSuffix(name, ".tmp") {
159				continue
160			}
161			b, readErr := os.ReadFile(filepath.Join(s.dir, name)) //nolint:gosec // names from os.ReadDir(s.dir)
162			if readErr != nil {
163				return nil, fmt.Errorf("read manifest %s: %w", name, readErr)
164			}
165			var m LocalManifest
166			if err := json.Unmarshal(b, &m); err != nil {
167				// Skip files we can't decode — they may be stale or
168				// from a future schema. Listing must keep working.
169				continue
170			}
171			manifests = append(manifests, m)
172		}
173		sort.SliceStable(manifests, func(i, j int) bool {
174			return manifests[i].StartedAt.After(manifests[j].StartedAt)
175		})
176		return manifests, nil
177	}
178	
179	// FindByRunID returns the manifest whose RunID equals runID. The bool
180	// reports whether a match was found; when false the returned manifest is
181	// the zero value. Returns an error only when the underlying directory read
182	// itself fails.
183	//
184	// Filenames are <timestamp>-<runID>.json, so the lookup is a single Glob +
185	// one file read rather than scanning every manifest in the directory.
186	func (s *LocalManifestStore) FindByRunID(ctx context.Context, runID string) (LocalManifest, bool, error) {
187		_ = ctx
188		if err := validateRunID(runID); err != nil {
189			return LocalManifest{}, false, fmt.Errorf("invalid run ID: %w", err)
190		}
191		matches, err := filepath.Glob(filepath.Join(s.dir, "*-"+runID+".json"))
192		if err != nil {
193			return LocalManifest{}, false, fmt.Errorf("glob manifest %s: %w", runID, err)
194		}
195		if len(matches) == 0 {
196			return LocalManifest{}, false, nil
197		}
198		b, err := os.ReadFile(matches[0])
199		if err != nil {
200			if errors.Is(err, os.ErrNotExist) {
201				return LocalManifest{}, false, nil
202			}
203			return LocalManifest{}, false, fmt.Errorf("read manifest %s: %w", filepath.Base(matches[0]), err)
204		}
205		var m LocalManifest
206		if err := json.Unmarshal(b, &m); err != nil {
207			return LocalManifest{}, false, fmt.Errorf("decode manifest %s: %w", filepath.Base(matches[0]), err)
208		}
209		return m, true, nil
210	}
211	
212	// ResolveByRunID matches a (possibly partial) run ID against the supplied
213	// manifest list. Exact match wins; otherwise unique-prefix wins. Returns
214	// a slice (always length 1 on success) so callers handle the not-found
215	// and ambiguous cases via the error.
216	//
217	// The shape mirrors what show and clean both want: an exact 12-hex match
218	// resolves O(1), a unique prefix expands to exactly one manifest, and any
219	// other case produces a user-readable error listing the candidates.
220	func ResolveByRunID(manifests []LocalManifest, runID string) ([]LocalManifest, error) {
221		for _, m := range manifests {
222			if m.RunID == runID {
223				return []LocalManifest{m}, nil
224			}
225		}
226		var prefixMatches []LocalManifest
227		for _, m := range manifests {
228			if strings.HasPrefix(m.RunID, runID) {
229				prefixMatches = append(prefixMatches, m)
230			}
231		}
232		switch len(prefixMatches) {
233		case 0:
234			return nil, fmt.Errorf("no investigation found with run id or prefix %q", runID)
235		case 1:
236			return prefixMatches, nil
237		default:
238			return nil, ambiguousRunIDError(prefixMatches, runID)
239		}
240	}
241	
242	// ambiguousRunIDError formats a list of candidate run ids for the user
243	// to choose from. When runID is empty, the header asks the user to pass a
244	// run id; otherwise it reports the ambiguous prefix.
245	func ambiguousRunIDError(candidates []LocalManifest, runID string) error {
246		sorted := append([]LocalManifest(nil), candidates...)
247		sort.SliceStable(sorted, func(i, j int) bool {
248			return sorted[i].StartedAt.After(sorted[j].StartedAt)
249		})
250		var b strings.Builder
251		if runID == "" {
252			b.WriteString("multiple investigations available — pass a run id (or unique prefix):\n")
253		} else {
254			fmt.Fprintf(&b, "ambiguous run id prefix %q matches multiple investigations:\n", runID)
255		}
256		for _, m := range sorted {
257			fmt.Fprintf(&b, "  %s  %s\n", m.RunID, m.Topic)
258		}
259		return errors.New(strings.TrimRight(b.String(), "\n"))
260	}
261	
262	// Latest returns the most recent manifest in the store, identified by the
263	// lexicographically largest filename (filenames are <timestamp>-<runID>.json
264	// where the timestamp prefix sorts chronologically). The bool reports
265	// whether the store has any manifests; when false the returned manifest is
266	// the zero value. Avoids reading every manifest just to pick the newest one.
267	func (s *LocalManifestStore) Latest(ctx context.Context) (LocalManifest, bool, error) {
268		_ = ctx
269		entries, err := os.ReadDir(s.dir)
270		if err != nil {
271			if errors.Is(err, os.ErrNotExist) {
272				return LocalManifest{}, false, nil
273			}
274			return LocalManifest{}, false, fmt.Errorf("read investigations manifests dir: %w", err)
275		}
276		var latest string
277		for _, e := range entries {
278			if e.IsDir() {
279				continue
280			}
281			name := e.Name()
282			if !strings.HasSuffix(name, ".json") || strings.HasSuffix(name, ".tmp") {
283				continue
284			}
285			if name > latest {
286				latest = name
287			}
288		}
289		if latest == "" {
290			return LocalManifest{}, false, nil
291		}
292		b, err := os.ReadFile(filepath.Join(s.dir, latest)) //nolint:gosec // name from os.ReadDir(s.dir)
293		if err != nil {
294			return LocalManifest{}, false, fmt.Errorf("read manifest %s: %w", latest, err)
295		}
296		var m LocalManifest
297		if err := json.Unmarshal(b, &m); err != nil {
298			return LocalManifest{}, false, fmt.Errorf("decode manifest %s: %w", latest, err)
299		}
300		return m, true, nil
301	}
302	
303	// manifestFilename returns the on-disk filename for m. Format:
304	// <timestamp>-<run-id>.json, where timestamp is the UTC StartedAt formatted
305	// as 20060102T150405. The timestamp prefix sorts manifests
306	// chronologically by directory listing, making `ls` output match List's
307	// newest-first ordering by simple reverse.
308	func manifestFilename(m LocalManifest) string {
309		stamp := m.StartedAt.UTC().Format("20060102T150405")
310		return stamp + "-" + m.RunID + ".json"
311	}
312	
313	// PathFor returns the on-disk path of the manifest file for m. The path
314	// is computed deterministically from m.StartedAt + m.RunID (the same
315	// inputs Write uses to choose its destination), so callers can use this
316	// to delete a manifest record without scanning the directory.
317	func (s *LocalManifestStore) PathFor(m LocalManifest) string {
318		return filepath.Join(s.dir, manifestFilename(m))
319	}
320

