	// Outcome is the terminal outcome of the run. One of: "quorum",
	// "stalled", "paused", "cancelled".
	Outcome string `json:"outcome"`

	// StancesByAgent records the LAST stance each agent expressed in
	// the run, keyed by agent name. Empty when the run terminated
	// without any stances being recorded.
	StancesByAgent map[string]string `json:"stances_by_agent,omitempty"`

	// StartedAt is when the run was initiated.
	StartedAt time.Time `json:"started_at"`

	// EndedAt is when the run terminated.
	EndedAt time.Time `json:"ended_at"`
}

// LocalManifestStore wraps the directory that holds persisted LocalManifest
// JSON files for one repository.
type LocalManifestStore struct {
	dir string
}

// NewLocalManifestStore creates a LocalManifestStore rooted at
// <git-common-dir>/entire-investigations/manifests. Resolves the common dir
// via session.GetGitCommonDir, so this requires a git repository context.
func NewLocalManifestStore(ctx context.Context) (*LocalManifestStore, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("get git common dir: %w", err)
	}
	return &LocalManifestStore{
		dir: filepath.Join(commonDir, InvestigationsDirName, manifestsSubdirName),
	}, nil
}

// NewLocalManifestStoreWithDir creates a LocalManifestStore rooted at dir.
// Useful for tests that do not want to depend on a real git repository.
func NewLocalManifestStoreWithDir(dir string) *LocalManifestStore {
	return &LocalManifestStore{dir: dir}
}

// Write persists m to the manifests directory using a deterministic filename
// derived from m.StartedAt and m.RunID. Existing files are overwritten — the
// timestamp+run-id combination is unique by construction (each run has a fresh
// run ID and a different start time).
func (s *LocalManifestStore) Write(ctx context.Context, m LocalManifest) error {
	_ = ctx // Reserved for future use.

	if err := validateRunID(m.RunID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}
	if m.StartedAt.IsZero() {
		return errors.New("manifest StartedAt is required")
	}

	if err := os.MkdirAll(s.dir, 0o750); err != nil {
		return fmt.Errorf("create investigations manifests dir: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(m, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal manifest: %w", err)
	}

	finalPath := filepath.Join(s.dir, manifestFilename(m))
	if err := jsonutil.WriteFileAtomic(finalPath, data, 0o644); err != nil {
		return fmt.Errorf("write manifest: %w", err)
	}
	return nil
}

// List returns every manifest in the store sorted newest first by StartedAt.
// A missing directory is treated as an empty list (nil, nil) — useful for
// callers that want to render `--findings` even when no investigation has
// ever been run in this repo.
func (s *LocalManifestStore) List(ctx context.Context) ([]LocalManifest, error) {
	_ = ctx // Reserved for future use.

	entries, err := os.ReadDir(s.dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read investigations manifests dir: %w", err)
	}

	manifests := make([]LocalManifest, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if !strings.HasSuffix(name, ".json") || strings.HasSuffix(name, ".tmp") {
			continue
		}
		b, readErr := os.ReadFile(filepath.Join(s.dir, name)) //nolint:gosec // names from os.ReadDir(s.dir)
		if readErr != nil {
			return nil, fmt.Errorf("read manifest %s: %w", name, readErr)
		}
		var m LocalManifest
		if err := json.Unmarshal(b, &m); err != nil {
			// Skip files we can't decode — they may be stale or
			// from a future schema. Listing must keep working.
			continue
		}
		manifests = append(manifests, m)
	}
	sort.SliceStable(manifests, func(i, j int) bool {
		return manifests[i].StartedAt.After(manifests[j].StartedAt)
	})
	return manifests, nil
}

// FindByRunID returns the manifest whose RunID equals runID. The bool
// reports whether a match was found; when false the returned manifest is
// the zero value. Returns an error only when the underlying directory read
// itself fails.
//
// Filenames are <timestamp>-<runID>.json, so the lookup is a single Glob +
// one file read rather than scanning every manifest in the directory.
func (s *LocalManifestStore) FindByRunID(ctx context.Context, runID string) (LocalManifest, bool, error) {
	_ = ctx
	if err := validateRunID(runID); err != nil {
		return LocalManifest{}, false, fmt.Errorf("invalid run ID: %w", err)
	}
	matches, err := filepath.Glob(filepath.Join(s.dir, "*-"+runID+".json"))
	if err != nil {
		return LocalManifest{}, false, fmt.Errorf("glob manifest %s: %w", runID, err)
	}
	if len(matches) == 0 {
		return LocalManifest{}, false, nil
	}
	b, err := os.ReadFile(matches[0])
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return LocalManifest{}, false, nil
		}
		return LocalManifest{}, false, fmt.Errorf("read manifest %s: %w", filepath.Base(matches[0]), err)
	}
	var m LocalManifest
	if err := json.Unmarshal(b, &m); err != nil {
		return LocalManifest{}, false, fmt.Errorf("decode manifest %s: %w", filepath.Base(matches[0]), err)
	}
	return m, true, nil
}

// ResolveByRunID matches a (possibly partial) run ID against the supplied
// manifest list. Exact match wins; otherwise unique-prefix wins. Returns
// a slice (always length 1 on success) so callers handle the not-found
// and ambiguous cases via the error.
//
// The shape mirrors what show and clean both want: an exact 12-hex match
// resolves O(1), a unique prefix expands to exactly one manifest, and any
// other case produces a user-readable error listing the candidates.
func ResolveByRunID(manifests []LocalManifest, runID string) ([]LocalManifest, error) {
	for _, m := range manifests {
		if m.RunID == runID {
			return []LocalManifest{m}, nil
		}
	}
	var prefixMatches []LocalManifest
	for _, m := range manifests {
		if strings.HasPrefix(m.RunID, runID) {
			prefixMatches = append(prefixMatches, m)
		}
	}
	switch len(prefixMatches) {
	case 0:
		return nil, fmt.Errorf("no investigation found with run id or prefix %q", runID)
	case 1:
		return prefixMatches, nil
	default:
		return nil, ambiguousRunIDError(prefixMatches, runID)
	}
}

// ambiguousRunIDError formats a list of candidate run ids for the user
// to choose from. When runID is empty, the header asks the user to pass a
// run id; otherwise it reports the ambiguous prefix.
func ambiguousRunIDError(candidates []LocalManifest, runID string) error {
	sorted := append([]LocalManifest(nil), candidates...)
	sort.SliceStable(sorted, func(i, j int) bool {
		return sorted[i].StartedAt.After(sorted[j].StartedAt)
	})
	var b strings.Builder
	if runID == "" {
		b.WriteString("multiple investigations available — pass a run id (or unique prefix):\n")
	} else {
		fmt.Fprintf(&b, "ambiguous run id prefix %q matches multiple investigations:\n", runID)
	}
	for _, m := range sorted {
		fmt.Fprintf(&b, "  %s  %s\n", m.RunID, m.Topic)
	}
	return errors.New(strings.TrimRight(b.String(), "\n"))
}

// Latest returns the most recent manifest in the store, identified by the
// lexicographically largest filename (filenames are <timestamp>-<runID>.json
// where the timestamp prefix sorts chronologically). The bool reports
// whether the store has any manifests; when false the returned manifest is
// the zero value. Avoids reading every manifest just to pick the newest one.
func (s *LocalManifestStore) Latest(ctx context.Context) (LocalManifest, bool, error) {
	_ = ctx
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return LocalManifest{}, false, nil
		}
		return LocalManifest{}, false, fmt.Errorf("read investigations manifests dir: %w", err)
	}
	var latest string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasSuffix(name, ".json") || strings.HasSuffix(name, ".tmp") {
			continue
		}
		if name > latest {
			latest = name
		}
	}
	if latest == "" {
		return LocalManifest{}, false, nil
	}
	b, err := os.ReadFile(filepath.Join(s.dir, latest)) //nolint:gosec // name from os.ReadDir(s.dir)
	if err != nil {
		return LocalManifest{}, false, fmt.Errorf("read manifest %s: %w", latest, err)
	}
	var m LocalManifest
	if err := json.Unmarshal(b, &m); err != nil {
		return LocalManifest{}, false, fmt.Errorf("decode manifest %s: %w", latest, err)
	}
	return m, true, nil
}

// manifestFilename returns the on-disk filename for m. Format:
// <timestamp>-<run-id>.json, where timestamp is the UTC StartedAt formatted
// as 20060102T150405. The timestamp prefix sorts manifests
// chronologically by directory listing, making `ls` output match List's
// newest-first ordering by simple reverse.
func manifestFilename(m LocalManifest) string {
	stamp := m.StartedAt.UTC().Format("20060102T150405")
	return stamp + "-" + m.RunID + ".json"
}

// PathFor returns the on-disk path of the manifest file for m. The path
// is computed deterministically from m.StartedAt + m.RunID (the same
// inputs Write uses to choose its destination), so callers can use this
// to delete a manifest record without scanning the directory.
func (s *LocalManifestStore) PathFor(m LocalManifest) string {
	return filepath.Join(s.dir, manifestFilename(m))
}

package investigate

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// InvestigationsDirName is the directory name (under git common dir) where
// investigation runs persist their per-run artifacts (findings.md +
// state.json).
const InvestigationsDirName = "entire-investigations"

// stateFileName is the on-disk name for the per-run state file inside the
// run directory.
const stateFileName = "state.json"

// runIDPattern is the validation regex for investigation run IDs: exactly
// 12 lowercase hex characters. Shares the checkpoint-id format via
// id.Pattern.
var runIDPattern = regexp.MustCompile("^" + id.Pattern + "$")

// RunState is the persisted state of an investigation run, sufficient to
// resume after a crash, Ctrl+C, or `--continue`.
//
// Round semantics: CompletedRounds counts how many full passes through
// every agent have finished — it is 0 mid-round-1, increments to 1 once
// every agent has had its first turn, and so on. By contrast,
// TurnStance.Round records the 1-indexed round each individual turn
// belongs to. The two fields look similar but represent different things;
// readers must pick the one that matches the question they're asking.
type RunState struct {
	RunID           string       `json:"run_id"`
	Topic           string       `json:"topic"`
	Agents          []string     `json:"agents"`
	MaxTurns        int          `json:"max_turns"`
	Quorum          int          `json:"quorum"`
	CompletedRounds int          `json:"completed_rounds"`
	Turn            int          `json:"turn"`           // overall turn index across rounds
	NextAgentIdx    int          `json:"next_agent_idx"` // index into Agents for the NEXT turn
	Stances         []TurnStance `json:"stances,omitempty"`
	FindingsDoc     string       `json:"findings_doc"` // absolute path
	StartingSHA     string       `json:"starting_sha"`
	StartedAt       time.Time    `json:"started_at"`
	UpdatedAt       time.Time    `json:"updated_at"`

	// PendingTurn is the agent-writable section. After each agent turn the
	// agent sets this to its stance + a short note. The loop reads it
	// after the agent process exits, validates it, appends a TurnStance to
	// Stances[], clears PendingTurn, advances cursors, persists.
	PendingTurn *PendingTurn `json:"pending_turn,omitempty"`
}

// PendingTurn is the agent-written stance for the most recent turn. The
// agent populates this before exiting; the loop reads it, appends to
// Stances[], and clears the field. The `agent` and `turn` fields are
// unambiguous from context (the loop knows which turn it just ran), so the
// agent does not include them.
type PendingTurn struct {
	Stance string `json:"stance"`         // "approve" | "request-changes" | "reject"
	Note   string `json:"note,omitempty"` // short explanation; optional
}

// TurnStance is one agent's recorded stance for a turn.
//
// Round here is the 1-indexed round the turn belongs to (turn 1 of round
// 1, turn N+1 starts round 2, etc.) — distinct from
// RunState.CompletedRounds, which counts finished rounds.
type TurnStance struct {
	Round       int    `json:"round"`
	Turn        int    `json:"turn"` // overall turn number
	Agent       string `json:"agent"`
	Stance      string `json:"stance"` // "approve" | "request-changes" | "reject" | "unknown"
	PlanChanged bool   `json:"plan_changed"`
	Note        string `json:"note,omitempty"`
}

// StateStore is the runs-state directory wrapper. The root contains one
// sub-directory per run (named after the run ID), holding findings.md and
// state.json.
type StateStore struct {
	dir string
}

// NewStateStore creates a StateStore rooted at
// <git-common-dir>/entire-investigations. Resolves the common dir via
// session.GetGitCommonDir, so this requires a git repository context.
func NewStateStore(ctx context.Context) (*StateStore, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("get git common dir: %w", err)
	}
	return &StateStore{
		dir: filepath.Join(commonDir, InvestigationsDirName),
	}, nil
}

// NewStateStoreWithDir creates a StateStore rooted at dir. Useful for tests
// that don't want to depend on a real git repository.
func NewStateStoreWithDir(dir string) *StateStore {
	return &StateStore{dir: dir}
}

// Root returns the absolute path the store is rooted at. Useful for callers
// that need to derive sibling paths (e.g. findings.md alongside state.json).
func (s *StateStore) Root() string {
	return s.dir
}

// RunDir returns the absolute path of the per-run directory for runID,
// where findings.md and state.json both live. The directory may or may
// not exist on disk; callers that need it materialised should MkdirAll
// before writing.
func (s *StateStore) RunDir(runID string) string {
	return filepath.Join(s.dir, runID)
}

// Save writes the run state atomically (temp file + rename).
func (s *StateStore) Save(ctx context.Context, st *RunState) error {
	_ = ctx // Reserved for future use

	if err := validateRunID(st.RunID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}

	runDir := s.RunDir(st.RunID)
	if err := os.MkdirAll(runDir, 0o750); err != nil {
		return fmt.Errorf("create investigation run directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(st, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal run state: %w", err)
	}

	finalPath := s.runStatePath(st.RunID)
	if err := jsonutil.WriteFileAtomic(finalPath, data, 0o600); err != nil {
		return fmt.Errorf("write run state: %w", err)
	}
	return nil
}

// Load reads the run state for runID. Returns (nil, nil) when the file does
// not exist (treat as "no such run").
func (s *StateStore) Load(ctx context.Context, runID string) (*RunState, error) {
	_ = ctx // Reserved for future use

	if err := validateRunID(runID); err != nil {
		return nil, fmt.Errorf("invalid run ID: %w", err)
	}

	data, err := os.ReadFile(s.runStatePath(runID))
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // nil,nil indicates run not found
		}
		return nil, fmt.Errorf("read run state: %w", err)
	}

	var st RunState
	if err := json.Unmarshal(data, &st); err != nil {
		return nil, fmt.Errorf("unmarshal run state: %w", err)
	}
	return &st, nil
}

// List returns all persisted run states. Returns nil (and no error) when the
// state directory does not exist.
func (s *StateStore) List(ctx context.Context) ([]*RunState, error) {
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("read investigations directory: %w", err)
	}

	var states []*RunState
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		runID := entry.Name()
		if err := validateRunID(runID); err != nil {
			// Skip directories that don't match the run-ID format — they
			// are not ours (e.g. the manifests/ sibling).
			continue
		}
		st, loadErr := s.Load(ctx, runID)
		if loadErr != nil {
			continue
		}
		if st == nil {
			continue
		}
		states = append(states, st)
	}
	return states, nil
}

// Clear removes the persisted state for runID. Missing files are treated as a
// successful clear (no-op).
func (s *StateStore) Clear(ctx context.Context, runID string) error {
	_ = ctx // Reserved for future use

	if err := validateRunID(runID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}

	if err := os.Remove(s.runStatePath(runID)); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("remove run state file: %w", err)
	}
	return nil
}

// runStatePath returns the on-disk path for runID's state file.
func (s *StateStore) runStatePath(runID string) string {
	return filepath.Join(s.RunDir(runID), stateFileName)
}

// validateRunID enforces that runID is exactly 12 lowercase hex characters.
// Anything else is rejected to prevent path traversal and to keep the format
// stable for sharded directory layouts elsewhere in the codebase.
func validateRunID(runID string) error {
	if runID == "" {
		return errors.New("run ID cannot be empty")
	}
	if !runIDPattern.MatchString(runID) {
		return fmt.Errorf("invalid run ID %q: must be 12 lowercase hex characters", runID)
	}
	return nil
}

// IsValidRunID reports whether runID matches the 12-lowercase-hex format.
// Exposed for callers in other packages (e.g. lifecycle adoption) that need
// to validate without taking on the error-formatting overhead.
func IsValidRunID(runID string) bool {
	return runID != "" && runIDPattern.MatchString(runID)
}

package investigate

// loop.go implements the round-robin investigation loop driver.
//
// The loop runs a fixed list of agents in a strict round-robin order. For
// each turn it:
//
//  1. Fingerprints the findings file BEFORE the turn.
//  2. Composes a prompt via ComposeInvestigatePrompt.
//  3. Spawns the agent via Spawner.BuildCmd with ENTIRE_INVESTIGATE_* env
//     populated by AppendInvestigateEnv.
//  4. Discards the agent's stdout/stderr — the lifecycle hooks capture the
//     full session transcript on the shadow branch and condense it onto
//     entire/checkpoints/v1 on the next commit.
//  5. Waits for the agent to exit. Re-fingerprints the findings doc.
//  6. Reloads state.json from disk. The agent has written its stance into
//     state.PendingTurn; the loop validates it, appends a TurnStance, and
//     clears PendingTurn.
//  7. Records a TurnStance in the persisted RunState and notifies the
//     ProgressSink (TUI dashboard or headless text writer).
//  8. Decides whether to terminate (quorum, stalled, paused, cancelled) or
//     advance to the next agent.
//
// The loop is single-threaded: each turn waits for the previous to exit
// before starting. This keeps the order of recorded stances deterministic
// and avoids racing two agents on the same shared findings doc.
//
// Privacy: operational metadata only. Prompts, file bodies, agent stdout,
// and commit messages are NEVER logged (CLAUDE.md privacy rule).

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/spawn"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// LoopDeps collects the runtime-injectable hooks RunInvestigateLoop needs.
type LoopDeps struct {
	// SpawnerFor maps an agent name → Spawner. Returns nil for an unknown
	// agent name, in which case the loop pauses with an error.
	SpawnerFor func(agentName string) spawn.Spawner

	// States persists/loads RunState across turns. In production this is
	// a *StateStore rooted at <git-common-dir>/entire-investigations.
	States *StateStore

	// Progress receives turn lifecycle events. Production wires either a
	// tuiProgressSink (TTY) or textProgressSink (non-TTY). nil is treated
	// as nullProgressSink (no-op).
	Progress ProgressSink

	// Now returns the current time. Defaults to time.Now if nil.
	Now func() time.Time
}

// LoopInput carries everything RunInvestigateLoop needs that isn't a hook.
type LoopInput struct {
	RunID        string    // 12-hex
	Topic        string    // human-readable subject of the investigation
	Agents       []string  // ordered, length >= 1
	MaxTurns     int       // per-agent turn budget; 0 → 3
	Quorum       int       // approvals needed; 0 → len(Agents)
	AlwaysPrompt string    // optional, appended verbatim to every prompt
	FindingsDoc  string    // absolute path
	StartingSHA  string    // git HEAD when `entire investigate` was invoked
	Resume       *RunState // when non-nil, resume from this state
}

// LoopOutcome describes how the loop ended.
type LoopOutcome string

const (
	// OutcomeQuorum means the most recent completed round produced enough
	// approve stances to meet Quorum. The loop ends successfully.
	OutcomeQuorum LoopOutcome = "quorum"
	// OutcomeStalled means the per-agent turn budget was exhausted without
	// reaching quorum. The investigation produced findings but no
	// consensus.
	OutcomeStalled LoopOutcome = "stalled"
	// OutcomePaused means two consecutive agent invocations failed (process
	// error, non-zero exit). The loop stops so the user can investigate;
	// state is preserved for `--continue`.
	OutcomePaused LoopOutcome = "paused"
	// OutcomeCancelled means the context was cancelled (Ctrl+C, parent
	// command shutdown). State is preserved for resume.
	OutcomeCancelled LoopOutcome = "cancelled"
)

// LoopResult is the loop's final report.
type LoopResult struct {
	Outcome LoopOutcome
	State   *RunState
	// Err holds the most recent per-turn spawn error, if any. Informational:
	// when Outcome is Quorum/Stalled it is typically nil. When Outcome is
	// Paused this surfaces the underlying agent failure.
	Err error
}

// pauseAfterConsecutiveFailures is the number of back-to-back per-turn
// agent failures that trigger OutcomePaused. Two: one failure could be
// transient, two strongly suggests a configuration problem the user must
// fix before continuing.
const pauseAfterConsecutiveFailures = 2

// defaultMaxTurns is the per-agent turn budget when LoopInput.MaxTurns is 0.
const defaultMaxTurns = 2

// stanceApprove and friends pin the stance vocabulary so callers can compare
// without typo risk. The PendingTurn validator normalises to one of these
// or "unknown".
const (
	stanceApprove        = "approve"
	stanceRequestChanges = "request-changes"
	stanceReject         = "reject"
	stanceUnknown        = "unknown"
)

// RunInvestigateLoop runs the round-robin investigation loop until it
// reaches quorum, stalls, gets paused, or the context is cancelled.
//
// On every turn the function persists state via deps.States so a crash mid-
// turn leaves a recoverable RunState on disk. The returned LoopResult is
// always populated, even on context cancellation.
//
// The function returns (result, error) where error is non-nil only for
// programmer errors (invalid input, missing dependencies). Per-turn agent
// failures are reflected in result.Outcome and result.Err, not the return
// error.
func RunInvestigateLoop(ctx context.Context, in LoopInput, deps LoopDeps) (LoopResult, error) {
	if err := validateLoopInput(in); err != nil {
		return LoopResult{}, err
	}
	if deps.States == nil {
		return LoopResult{}, errors.New("LoopDeps.States is required")
	}
	if deps.SpawnerFor == nil {
		return LoopResult{}, errors.New("LoopDeps.SpawnerFor is required")
	}
	if deps.Progress == nil {
		deps.Progress = nullProgressSink{}
	}
	now := deps.Now
	if now == nil {
		now = time.Now
	}

	maxTurnsPerAgent := in.MaxTurns
	if maxTurnsPerAgent == 0 {
		maxTurnsPerAgent = defaultMaxTurns
	}
	quorum := in.Quorum
	if quorum == 0 {
		quorum = len(in.Agents)
	}
	maxOverall := maxTurnsPerAgent * len(in.Agents)

	state := initLoopState(in, now, maxTurnsPerAgent, quorum)

	// Persist the initial state once so external observers (status command,
	// `--continue`) see the run as soon as the loop starts.
	if err := deps.States.Save(ctx, state); err != nil {
		return LoopResult{State: state}, fmt.Errorf("save initial run state: %w", err)
	}

	cfg := turnConfig{
		input:       in,
		deps:        deps,
		now:         now,
		quorum:      quorum,
		maxPerAgent: maxTurnsPerAgent,
		stateDoc:    deps.States.runStatePath(in.RunID),
	}
	consecutiveFails := 0
	var lastErr error

	for state.Turn < maxOverall {
		if ctx.Err() != nil {
			// Cancellation is a normal terminal outcome surfaced through
			// LoopResult.Outcome. Contract is "always-returns-result,
			// error only for programmer bugs".
			deps.Progress.RunFinished(OutcomeCancelled)
			//nolint:nilerr // ctx cancellation is reported via Outcome, not the error return
			return LoopResult{Outcome: OutcomeCancelled, State: state, Err: lastErr}, nil
		}

		outcome := runOneTurn(ctx, cfg, state)
		if outcome.failed {
			lastErr = outcome.err
			consecutiveFails++
			if consecutiveFails >= pauseAfterConsecutiveFailures {
				deps.Progress.RunFinished(OutcomePaused)
				return LoopResult{Outcome: OutcomePaused, State: state, Err: lastErr}, nil
			}
		} else {
			consecutiveFails = 0
		}
		advanceAgent(state)
		if saveErr := deps.States.Save(ctx, state); saveErr != nil {
			logging.Debug(ctx, "investigate: save state after turn",
				sErr(saveErr), sRun(in.RunID))
		}
		if state.NextAgentIdx == 0 {
			if approveCountInRound(state.Stances, outcome.round) >= quorum {
				deps.Progress.RunFinished(OutcomeQuorum)
				return LoopResult{Outcome: OutcomeQuorum, State: state, Err: nil}, nil
			}
		}
	}

	deps.Progress.RunFinished(OutcomeStalled)
	return LoopResult{Outcome: OutcomeStalled, State: state, Err: lastErr}, nil
}

// turnConfig packages the immutable knobs runOneTurn needs. Splitting these
// out from RunInvestigateLoop's call frame keeps the per-turn helper
// signature tight without re-deriving values on every iteration.
type turnConfig struct {
	input       LoopInput
	deps        LoopDeps
	now         func() time.Time
	quorum      int
	maxPerAgent int
	stateDoc    string // absolute path to state.json (passed to the agent)
}

// turnOutcome reports the post-turn state runOneTurn produces. The loop
// uses these flags to drive the consecutive-failure counter and the round
// boundary check; every other side effect (state mutation, persistence,
// logging) happens inside runOneTurn.
type turnOutcome struct {
	round  int
	failed bool
	err    error
}

// runOneTurn executes a single agent turn and records the resulting
// TurnStance on state.Stances. It mutates state.Turn (incremented) and
// state.Stances; the caller is responsible for advanceAgent and the post-
// turn Save.
func runOneTurn(ctx context.Context, cfg turnConfig, state *RunState) turnOutcome {
	in := cfg.input
	deps := cfg.deps
	agentName := state.Agents[state.NextAgentIdx]
	state.Turn++
	round := ((state.Turn - 1) / len(state.Agents)) + 1

	preFindings := fileFingerprint(ctx, in.FindingsDoc)

	deps.Progress.TurnStarted(agentName, state.Turn, round, cfg.maxPerAgent)

	spawner := deps.SpawnerFor(agentName)
	if spawner == nil {
		err := fmt.Errorf("no spawner for agent %q", agentName)
		recordFailureStance(state, round, agentName, err, cfg.now)
		deps.Progress.TurnFinished(agentName, state.Turn, stanceUnknown, 0, true, err, "")
		return turnOutcome{round: round, failed: true, err: err}
	}

	prompt := ComposeInvestigatePrompt(ComposeInput{
		Topic:        in.Topic,
		AgentName:    agentName,
		Round:        round,
		MaxTurns:     cfg.maxPerAgent,
		Turn:         state.Turn,
		AlwaysPrompt: in.AlwaysPrompt,
		Files:        Files{Findings: in.FindingsDoc, State: cfg.stateDoc},
	})
	env := AppendInvestigateEnv(os.Environ(), AppendOptions{
		AgentName:   agentName,
		RunID:       in.RunID,
		Topic:       in.Topic,
		FindingsDoc: in.FindingsDoc,
		StateDoc:    cfg.stateDoc,
		StartingSHA: in.StartingSHA,
	})
	cmd := spawner.BuildCmd(ctx, env, prompt)

	// Agent stdout/stderr are captured by the lifecycle hooks into the
	// session transcript (full.jsonl) and condensed onto
	// entire/checkpoints/v1 on commit. Discard the raw streams here.
	cmd.Stdout = io.Discard
	cmd.Stderr = io.Discard

	logging.Info(ctx, "investigate: turn start",
		sRun(in.RunID), sAgent(agentName), sTurn(state.Turn), sRound(round))

	turnStart := cfg.now()
	runErr := cmd.Run()
	turnDuration := cfg.now().Sub(turnStart)

	postFindings := fileFingerprint(ctx, in.FindingsDoc)

	if runErr != nil {
		turn := TurnStance{
			Round:       round,
			Turn:        state.Turn,
			Agent:       agentName,
			Stance:      stanceUnknown,
			PlanChanged: preFindings != postFindings,
			Note:        "spawn error: " + runErr.Error(),
		}
		state.Stances = append(state.Stances, turn)
		state.PendingTurn = nil
		updateRoundCounter(state)
		state.UpdatedAt = cfg.now()
		logging.Warn(ctx, "investigate: turn failed",
			sRun(in.RunID), sAgent(agentName),
			sTurn(state.Turn), sRound(round),
			slogString("err", runErr.Error()))
		deps.Progress.TurnFinished(agentName, state.Turn, stanceUnknown, turnDuration, true, runErr, "")
		return turnOutcome{round: round, failed: true, err: runErr}
	}

	// Reload state from disk: the agent (running with cfg.stateDoc on the
	// filesystem) may have written PendingTurn. Merge that into the
	// in-memory state, then clear it on disk after recording the stance.
	stance, note, hasPending := readPendingTurn(ctx, deps.States, in.RunID, state)
	turn := TurnStance{
		Round:       round,
		Turn:        state.Turn,
		Agent:       agentName,
		Stance:      stance,
		PlanChanged: preFindings != postFindings,
		Note:        note,
	}
	state.Stances = append(state.Stances, turn)
	state.PendingTurn = nil
	updateRoundCounter(state)
	state.UpdatedAt = cfg.now()
	logging.Info(ctx, "investigate: turn end",
		sRun(in.RunID), sAgent(agentName),
		sTurn(state.Turn), sRound(round),
		slogString("stance", stance),
		slogBool("plan_changed", turn.PlanChanged))

	// Treat a missing pending_turn as a soft failure: the agent ran cleanly
	// but produced no structured stance, so it should not count toward
	// quorum and consecutive misses must trip pause-on-failure. The
	// TurnStance is still recorded for diagnostics, but the loop sees this
	// as a failure for budget-control purposes.
	if !hasPending {
		logging.Warn(ctx, "investigate: turn missing pending_turn",
			sRun(in.RunID), sAgent(agentName),
			sTurn(state.Turn), sRound(round))
		missingPending := errors.New("agent did not write pending_turn to state.json")
		deps.Progress.TurnFinished(agentName, state.Turn, stanceUnknown, turnDuration, true, missingPending, "")
		return turnOutcome{round: round, failed: true, err: missingPending}
	}

	deps.Progress.TurnFinished(agentName, state.Turn, stance, turnDuration, false, nil, note)
	return turnOutcome{round: round, failed: false}
}

// readPendingTurn loads the on-disk state.json (which the agent may have
// just rewritten) and returns the validated stance + note pair plus a
// "has pending" flag. The in-memory state is NOT mutated here — the caller
// owns the canonical state and clears PendingTurn after recording.
//
// Validation rules:
//   - missing file or unreadable file → ("unknown", "<diagnostic>", false)
//   - missing pending_turn field      → ("unknown", "missing pending_turn", false)
//   - stance not in the vocabulary    → ("unknown", "invalid stance: <value>", true)
//   - valid pending_turn              → (stance, note, true)
func readPendingTurn(ctx context.Context, store *StateStore, runID string, _ *RunState) (stance, note string, hasPending bool) {
	loaded, err := store.Load(ctx, runID)
	if err != nil {
		return stanceUnknown, "state read error: " + err.Error(), false
	}
	if loaded == nil || loaded.PendingTurn == nil {
		return stanceUnknown, "missing pending_turn", false
	}
	raw := strings.ToLower(strings.TrimSpace(loaded.PendingTurn.Stance))
	switch raw {
	case stanceApprove:
		return stanceApprove, strings.TrimSpace(loaded.PendingTurn.Note), true
	case stanceRequestChanges, "requestchanges", "request_changes":
		return stanceRequestChanges, strings.TrimSpace(loaded.PendingTurn.Note), true
	case stanceReject:
		return stanceReject, strings.TrimSpace(loaded.PendingTurn.Note), true
	default:
		// The agent wrote *something* — record it as an invalid-stance
		// pending_turn so the loop's "no pending" branch doesn't fire,
		// but mark the stance unknown so quorum can't count it.
		return stanceUnknown, "invalid stance: " + loaded.PendingTurn.Stance, true
	}
}

// validateLoopInput rejects programmer errors before the loop starts.
// These are bugs in the caller, not user errors, so they short-circuit
// with a plain error rather than entering the OutcomePaused/Stalled paths.
func validateLoopInput(in LoopInput) error {
	if err := validateRunID(in.RunID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}
	if len(in.Agents) == 0 {
		return errors.New("at least one agent is required")
	}
	if in.FindingsDoc == "" {
		return errors.New("FindingsDoc is required")
	}
	return nil
}

// initLoopState builds the starting RunState. When in.Resume is non-nil it
// takes its turn/round/idx + accumulated stances; otherwise it initialises
// a fresh state with Turn=0, NextAgentIdx=0.
func initLoopState(in LoopInput, now func() time.Time, maxTurns, quorum int) *RunState {
	if in.Resume != nil {
		st := *in.Resume
		// Always use the LoopInput's RunID/Agents/etc. — Resume is a
		// snapshot, but the caller is the source of truth for run config.
		st.RunID = in.RunID
		st.Topic = in.Topic
		st.Agents = append([]string(nil), in.Agents...)
		st.MaxTurns = maxTurns
		st.Quorum = quorum
		st.FindingsDoc = in.FindingsDoc
		st.StartingSHA = in.StartingSHA
		// Discard any pending_turn carried over from the resumed snapshot;
		// the next agent will write a fresh one.
		st.PendingTurn = nil
		if st.StartedAt.IsZero() {
			st.StartedAt = now()
		}
		st.UpdatedAt = now()
		return &st
	}
	t := now()
	return &RunState{
		RunID:           in.RunID,
		Topic:           in.Topic,
		Agents:          append([]string(nil), in.Agents...),
		MaxTurns:        maxTurns,
		Quorum:          quorum,
		CompletedRounds: 0,
		Turn:            0,
		NextAgentIdx:    0,
		FindingsDoc:     in.FindingsDoc,
		StartingSHA:     in.StartingSHA,
		StartedAt:       t,
		UpdatedAt:       t,
	}
}

// advanceAgent rolls NextAgentIdx forward modulo the agent count.
func advanceAgent(state *RunState) {
	state.NextAgentIdx = (state.NextAgentIdx + 1) % len(state.Agents)
}

// updateRoundCounter recomputes state.CompletedRounds from the current Turn.
// With N agents:
//   - Turn 1..N → round 1 in progress, completed rounds = 0
//   - Turn N+1..2N → round 2 in progress, completed rounds = 1
//
// The per-stance Round (TurnStance.Round) is 1-indexed and tracks the
// round each individual turn belongs to — the two fields are not
// interchangeable.
func updateRoundCounter(state *RunState) {
	state.CompletedRounds = state.Turn / len(state.Agents)
}

// approveCountInRound returns how many stances in the given round are
// "approve". Scans the slice rather than looking only at the tail so
// resumed runs (whose Stances slice may include earlier rounds) compute
// the right count.
func approveCountInRound(stances []TurnStance, round int) int {
	n := 0
	for _, s := range stances {
		if s.Round == round && s.Stance == stanceApprove {
			n++
		}
	}
	return n
}

// recordFailureStance appends a TurnStance with Stance="unknown" and a Note
// describing the failure. Used when the agent could not be spawned (no
// spawner, log-file open error). PlanChanged is false because nothing ran.
func recordFailureStance(state *RunState, round int, agent string, err error, now func() time.Time) {
	state.Stances = append(state.Stances, TurnStance{
		Round:  round,
		Turn:   state.Turn,
		Agent:  agent,
		Stance: stanceUnknown,
		Note:   "spawn error: " + err.Error(),
	})
	state.PendingTurn = nil
	updateRoundCounter(state)
	state.UpdatedAt = now()
}

// fileFingerprint returns "<size>:<unix-nanos-mtime>" for the file at path,
// or the empty string when the file is missing or unreadable. Used to
// drive PlanChanged: stat is enough to detect that the agent rewrote the
// findings doc, and avoids re-hashing a growing document on every turn.
//
// Stat errors are NOT surfaced: the loop must keep running when the
// findings file does not yet exist (turn 1 of a new run typically creates
// it from a template). A missing file is detected downstream by comparing
// the empty fingerprint before vs. after the turn.
func fileFingerprint(ctx context.Context, path string) string {
	info, err := os.Stat(path)
	if err != nil {
		logging.Debug(ctx, "investigate: stat findings doc failed",
			slogString("path", path), sErr(err))
		return ""
	}
	return fmt.Sprintf("%d:%d", info.Size(), info.ModTime().UnixNano())
}

// --- small slog helpers ---------------------------------------------------
//
// Tiny wrappers around the most common slog attributes to keep call-sites
// readable without sprinkling slog.String throughout the loop body.

func slogString(k, v string) any { return slog.String(k, v) }

func slogBool(k string, v bool) any { return slog.Bool(k, v) }

func sRun(runID string) any { return slog.String("run_id", runID) }

func sAgent(agent string) any { return slog.String("agent", agent) }

func sTurn(turn int) any { return slog.Int("turn", turn) }

func sRound(round int) any { return slog.Int("round", round) }

func sErr(err error) any {
	if err == nil {
		return slog.String("err", "")
	}
	return slog.String("err", err.Error())
}

package investigate

import (
	"context"
	"io"
	"sync"
	"time"

	tea "charm.land/bubbletea/v2"
)

// tuiProgressSink is a ProgressSink backed by a Bubble Tea program.
type tuiProgressSink struct {
	program *tea.Program

	mu       sync.Mutex
	started  bool
	finished bool

	done chan struct{} // closed when the tea.Program exits
}

// newTUIProgressSink builds a sink wired to cancel for Ctrl+C handling. The
// caller must invoke Start before any TurnStarted call and Wait after
// RunFinished.
//
// tea.WithoutSignalHandler keeps SIGINT routing on the cobra root's existing
// handler (which cancels the run context). The model's Ctrl+C path invokes
// the same cancel function so the two paths converge cleanly.
func newTUIProgressSink(topic, runID string, agents []string, maxTurns, quorum int, cancel context.CancelFunc, output io.Writer) *tuiProgressSink {
	model := newInvestigateTUIModel(topic, runID, agents, maxTurns, quorum, cancel)
	prog := tea.NewProgram(
		model,
		tea.WithOutput(output),
		tea.WithoutSignalHandler(),
	)
	return &tuiProgressSink{
		program: prog,
		done:    make(chan struct{}),
	}
}

// Start spawns the Bubble Tea program in its own goroutine. Subsequent
// calls are no-ops.
func (s *tuiProgressSink) Start() {
	s.mu.Lock()
	if s.started {
		s.mu.Unlock()
		return
	}
	s.started = true
	s.mu.Unlock()

	go func() {
		defer close(s.done)
		if _, err := s.program.Run(); err != nil {
			// Bubble Tea program errors are non-actionable in a background
			// goroutine. Run state and per-turn logs on disk remain
			// available.
			_ = err
		}
	}()
}

// Wait blocks until the Bubble Tea program exits. Safe to call after Start.
// If Start was never called, Wait returns immediately.
func (s *tuiProgressSink) Wait() {
	s.mu.Lock()
	started := s.started
	s.mu.Unlock()
	if !started {
		return
	}
	<-s.done
}

// TurnStarted implements ProgressSink. Drops the event if the program has
// already finished.
func (s *tuiProgressSink) TurnStarted(agent string, turn, _, _ int) {
	if !s.ready() {
		return
	}
	s.program.Send(turnStartedMsg{agent: agent, turn: turn})
}

// TurnFinished implements ProgressSink.
func (s *tuiProgressSink) TurnFinished(agent string, turn int, stance string, duration time.Duration, failed bool, err error, preview string) {
	if !s.ready() {
		return
	}
	s.program.Send(turnFinishedMsg{
		agent:    agent,
		turn:     turn,
		stance:   stance,
		duration: duration,
		failed:   failed,
		err:      err,
		findings: preview,
	})
}

// RunFinished implements ProgressSink. Blocks until the user dismisses the
// final dashboard (presses any key) so post-run output (the investigate
// footer in cmd.go) renders only after the TUI exits.
func (s *tuiProgressSink) RunFinished(outcome LoopOutcome) {
	s.mu.Lock()
	if s.finished {
		s.mu.Unlock()
		return
	}
	s.finished = true
	s.mu.Unlock()

	s.program.Send(runFinishedMsg{outcome: outcome})
	s.Wait()
}

// ready returns true when the program is running and not yet finished.
func (s *tuiProgressSink) ready() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.started && !s.finished
}

// Compile-time interface check.
var _ ProgressSink = (*tuiProgressSink)(nil)

package investigate

import (
	"context"
	"fmt"
	"strings"
	"sync"
	"time"

	"charm.land/bubbles/v2/spinner"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/entireio/cli/cmd/entire/cli/tuiutil"
)

// rowStatus is the per-agent terminal state shown in the STATUS column.
type rowStatus int

const (
	rowStatusQueued rowStatus = iota
	rowStatusRunning
	rowStatusDone
	rowStatusFailed
)

// timelineEntry is one row in the drill-in detail view's per-agent buffer.
// Entries are turn-granular: one on TurnStarted and one on TurnFinished
// (or TurnFinished with kind="failed" when the loop treated the turn as a
// failure).
type timelineEntry struct {
	when     time.Time
	turn     int
	kind     string // "started" | "finished" | "failed"
	stance   string
	duration time.Duration
	errStr   string
	findings string
}

// agentRow holds per-agent live state during the TUI run.
type agentRow struct {
	name         string
	status       rowStatus
	currentStart time.Time     // stamped on TurnStarted, zeroed on TurnFinished
	accumulated  time.Duration // sum of completed turn durations
	turnsTaken   int           // increments on TurnFinished (success or fail)
	maxTurns     int
	latestStance string // canonical: "approve" | "request-changes" | "reject" | ""
	lastErr      error
	buffer       []timelineEntry
}

// turnStartedMsg is sent when the loop begins an agent turn.
type turnStartedMsg struct {
	agent string
	turn  int
}

// turnFinishedMsg is sent when the loop finishes an agent turn (success or
// failure).
type turnFinishedMsg struct {
	agent    string
	turn     int
	stance   string
	duration time.Duration
	failed   bool
	err      error
	findings string // optional preview line parsed from the timeline doc
}

// runFinishedMsg is sent once when the loop terminates.
type runFinishedMsg struct {
	outcome LoopOutcome
}

// tickMsg drives spinner + running-duration refresh between turn events.
type tickMsg time.Time

// investigateTUIModel is the Bubble Tea model for the investigate dashboard.
type investigateTUIModel struct {
	topic           string
	runID           string
	rows            []agentRow
	rowIdx          map[string]int
	quorum          int
	approvals       int
	completedRounds int
	maxRounds       int

	finished bool
	outcome  LoopOutcome

	cancel     context.CancelFunc
	cancelOnce *sync.Once

	spinner    spinner.Model
	termWidth  int
	termHeight int

	detailMode   bool
	detailIdx    int
	detailScroll int
}

// newInvestigateTUIModel builds an initial model pre-populated with one row
// per agent. cancel is invoked when the user presses Ctrl+C inside the TUI.
func newInvestigateTUIModel(topic, runID string, agents []string, maxTurns, quorum int, cancel context.CancelFunc) investigateTUIModel {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))

	rows := make([]agentRow, len(agents))
	rowIdx := make(map[string]int, len(agents))
	for i, name := range agents {
		rows[i] = agentRow{
			name:     name,
			status:   rowStatusQueued,
			maxTurns: maxTurns,
		}
		rowIdx[name] = i
	}
	return investigateTUIModel{
		topic:      topic,
		runID:      runID,
		rows:       rows,
		rowIdx:     rowIdx,
		quorum:     quorum,
		maxRounds:  maxTurns,
		cancel:     cancel,
		cancelOnce: &sync.Once{},
		spinner:    sp,
		termWidth:  80,
		termHeight: 24,
	}
}

func tickCmd() tea.Cmd {
	return tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg {
		return tickMsg(t)
	})
}

// Init kicks off the spinner and the refresh tick.
func (m investigateTUIModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, tickCmd())
}

// Update handles all incoming messages.
func (m investigateTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case turnStartedMsg:
		return m.handleTurnStarted(msg), nil

	case turnFinishedMsg:
		return m.handleTurnFinished(msg), nil

	case runFinishedMsg:
		m.finished = true
		m.outcome = msg.outcome
		for i := range m.rows {
			if m.rows[i].status != rowStatusFailed {
				m.rows[i].status = rowStatusDone
			}
			if !m.rows[i].currentStart.IsZero() {
				m.rows[i].accumulated += time.Since(m.rows[i].currentStart)
				m.rows[i].currentStart = time.Time{}
			}
		}
		return m, nil

	case tickMsg:
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, tea.Batch(spinCmd, tickCmd())

	case spinner.TickMsg:
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, spinCmd

	case tea.WindowSizeMsg:
		m.termWidth = msg.Width
		m.termHeight = msg.Height
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.MouseWheelMsg:
		if !m.detailMode {
			return m, nil
		}
		switch msg.Button {
		case tea.MouseWheelUp:
			if m.detailScroll > 0 {
				m.detailScroll--
			}
		case tea.MouseWheelDown:
			if m.detailScroll < m.maxDetailScroll() {
				m.detailScroll++
			}
		}
		return m, nil
	}
	return m, nil
}

// handleTurnStarted marks the named agent as running and stamps the start
// time. Unknown agents are ignored (defensive — should not happen given
// rowIdx pre-population; dropping the message beats panicking).
func (m investigateTUIModel) handleTurnStarted(msg turnStartedMsg) investigateTUIModel {
	idx, ok := m.rowIdx[msg.agent]
	if !ok {
		return m
	}
	row := &m.rows[idx]
	row.status = rowStatusRunning
	row.currentStart = time.Now()
	row.buffer = append(row.buffer, timelineEntry{
		when: time.Now(),
		turn: msg.turn,
		kind: "started",
	})
	return m
}

// handleTurnFinished folds the just-completed turn into the row's
// accumulated state and updates the round counters.
func (m investigateTUIModel) handleTurnFinished(msg turnFinishedMsg) investigateTUIModel {
	idx, ok := m.rowIdx[msg.agent]
	if !ok {
		return m
	}
	row := &m.rows[idx]

	row.accumulated += msg.duration
	row.currentStart = time.Time{}
	row.turnsTaken++
	if msg.stance != "" && msg.stance != stanceUnknown {
		row.latestStance = msg.stance
	}
	if msg.failed {
		row.lastErr = msg.err
		if row.turnsTaken >= row.maxTurns {
			row.status = rowStatusFailed
		} else {
			row.status = rowStatusQueued
		}
	} else {
		row.status = rowStatusQueued
	}

	kind := "finished"
	if msg.failed {
		kind = "failed"
	}
	var errStr string
	if msg.err != nil {
		errStr = msg.err.Error()
	}
	row.buffer = append(row.buffer, timelineEntry{
		when:     time.Now(),
		turn:     msg.turn,
		kind:     kind,
		stance:   msg.stance,
		duration: msg.duration,
		errStr:   errStr,
		findings: msg.findings,
	})

	// Recompute round + approval counters from the full row set so it is
	// resilient to out-of-order messages and replays.
	totalTurns := 0
	approvals := 0
	for _, r := range m.rows {
		totalTurns += r.turnsTaken
		if r.latestStance == stanceApprove {
			approvals++
		}
	}
	if n := len(m.rows); n > 0 {
		m.completedRounds = totalTurns / n
	}
	m.approvals = approvals
	return m
}

// handleKey processes keyboard input.
func (m investigateTUIModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if m.finished && !m.detailMode {
		// Any key after finished dismisses.
		return m, tea.Quit
	}

	switch {
	case msg.Code == 'c' && msg.Mod == tea.ModCtrl:
		if m.detailMode {
			// Ctrl+C is ignored in detail mode; Esc first.
			return m, nil
		}
		m.cancelOnce.Do(m.cancel)
		return m, tea.Quit

	case msg.Code == 'o' && msg.Mod == tea.ModCtrl:
		if m.detailMode {
			m.detailMode = false
			return m, nil
		}
		m.detailMode = true
		if m.detailIdx < 0 || m.detailIdx >= len(m.rows) {
			m.detailIdx = 0
		}
		m.detailScroll = m.maxDetailScroll()
		return m, nil

	case msg.Code == tea.KeyEscape:
		if m.detailMode {
			m.detailMode = false
		}
		return m, nil

	case msg.Code == tea.KeyLeft:
		if m.detailMode && len(m.rows) > 0 {
			m.detailIdx = (m.detailIdx - 1 + len(m.rows)) % len(m.rows)
			m.detailScroll = m.maxDetailScroll()
		}
		return m, nil

	case msg.Code == tea.KeyRight:
		if m.detailMode && len(m.rows) > 0 {
			m.detailIdx = (m.detailIdx + 1) % len(m.rows)
			m.detailScroll = m.maxDetailScroll()
		}
		return m, nil

	case msg.Code == tea.KeyUp:
		if m.detailMode && m.detailScroll > 0 {
			m.detailScroll--
		}
		return m, nil

	case msg.Code == tea.KeyDown:
		if m.detailMode && m.detailScroll < m.maxDetailScroll() {
			m.detailScroll++
		}
		return m, nil
	}
	return m, nil
}

// maxDetailScroll returns the largest valid detailScroll value for the
// currently-focused agent's buffer (0 when the buffer is empty or no
// rows exist).
func (m investigateTUIModel) maxDetailScroll() int {
	if len(m.rows) == 0 {
		return 0
	}
	n := len(m.rows[m.detailIdx].buffer)
	if n == 0 {
		return 0
	}
	return n - 1
}

// View renders the current frame.
func (m investigateTUIModel) View() tea.View {
	var content string
	if m.detailMode && len(m.rows) > 0 {
		content = detailView(m.rows[m.detailIdx], m.detailScroll, m.termWidth, m.termHeight)
	} else {
		content = m.dashboardView()
	}
	v := tea.NewView(content)
	v.AltScreen = m.detailMode
	if m.detailMode {
		v.MouseMode = tea.MouseModeCellMotion
	}
	return v
}

// dashboardWidth returns the effective rendering width (defaulted when the
// terminal hasn't reported a size yet).
func (m investigateTUIModel) dashboardWidth() int {
	if m.termWidth <= 0 {
		return 80
	}
	return m.termWidth
}

// dashboardView renders the top banner, the table, and the footer hint.
func (m investigateTUIModel) dashboardView() string {
	var b strings.Builder

	m.writeLine(&b, m.titleLine())
	m.writeLine(&b, m.progressLine())
	b.WriteString("\n")
	m.writeLine(&b, m.headerLine())
	for _, row := range m.rows {
		m.writeLine(&b, m.renderRow(row))
	}
	b.WriteString("\n")
	if m.finished {
		m.writeLine(&b, m.outcomeLine())
		m.writeLine(&b, m.countsLine())
		m.writeLine(&b, "Press any key to exit.")
	} else {
		m.writeLine(&b, "Ctrl+O: detail · Ctrl+C: cancel")
	}
	return b.String()
}

func (m investigateTUIModel) writeLine(b *strings.Builder, line string) {
	b.WriteString(truncateDisplayWidth(line, m.dashboardWidth()))
	b.WriteString("\n")
}

func (m investigateTUIModel) titleLine() string {
	if m.topic == "" {
		return fmt.Sprintf("Investigating (run %s)", m.runID)
	}
	return fmt.Sprintf("Investigating: %q (run %s)", sanitizeDisplayText(m.topic), m.runID)
}

func (m investigateTUIModel) progressLine() string {
	totalTurns := 0
	for _, r := range m.rows {
		totalTurns += r.turnsTaken
	}
	maxOverall := m.maxRounds * len(m.rows)
	round := m.completedRounds + 1
	if m.finished {
		round = max(m.completedRounds, 1)
	}
	return fmt.Sprintf("Round %d/%d · %d of %d turns · quorum %d/%d approvals",
		round, m.maxRounds, totalTurns, maxOverall, m.approvals, m.quorum)
}

func (m investigateTUIModel) headerLine() string {
	return m.renderTableLine("AGENT", "STATUS", "DURATION", "TURN", "APPROVED")
}

func (m investigateTUIModel) renderRow(row agentRow) string {
	statusStr := m.statusString(row)
	durStr := formatRowDuration(row)
	turnStr := fmt.Sprintf("%d/%d", row.turnsTaken, row.maxTurns)
	approvedStr := formatStance(row.latestStance)
	return m.renderTableLine(row.name, statusStr, durStr, turnStr, approvedStr)
}

// statusString renders STATUS for a row, including the live dot spinner for
// the currently-running agent.
func (m investigateTUIModel) statusString(row agentRow) string {
	switch row.status {
	case rowStatusRunning:
		return m.spinner.View() + " running"
	case rowStatusDone:
		return "✓ done"
	case rowStatusFailed:
		return "✗ failed"
	case rowStatusQueued:
		fallthrough
	default:
		return "queued"
	}
}

// renderTableLine emits one row of the table padded to fixed column widths.
// APPROVED takes whatever's left after the four fixed columns.
func (m investigateTUIModel) renderTableLine(agent, status, duration, turn, approved string) string {
	const (
		agentWidth    = 20
		statusWidth   = 12
		durationWidth = 9
		turnWidth     = 6
		separators    = 8 // four two-space separators between five columns
		minWidth      = agentWidth + statusWidth + durationWidth + turnWidth + separators
	)
	termWidth := m.dashboardWidth()
	approvedWidth := max(termWidth-minWidth, 0)
	line := fmt.Sprintf("%s  %s  %s  %s  %s",
		padDisplayWidth(agent, agentWidth),
		padDisplayWidth(status, statusWidth),
		padDisplayWidth(duration, durationWidth),
		padDisplayWidth(turn, turnWidth),
		truncateDisplayWidth(approved, approvedWidth))
	return truncateDisplayWidth(line, termWidth)
}

// outcomeLine renders the post-run "Outcome: <name>" summary.
func (m investigateTUIModel) outcomeLine() string {
	if m.outcome == "" {
		return ""
	}
	return fmt.Sprintf("Outcome: %s", m.outcome)
}

// countsLine renders the per-stance totals at the end of the run.
func (m investigateTUIModel) countsLine() string {
	app, chg, rej, unk := 0, 0, 0, 0
	for _, r := range m.rows {
		switch r.latestStance {
		case stanceApprove:
			app++
		case stanceRequestChanges:
			chg++
		case stanceReject:
			rej++
		default:
			unk++
		}
	}
	return fmt.Sprintf("%d agent(s) — %d approved, %d request-changes, %d reject, %d unknown",
		len(m.rows), app, chg, rej, unk)
}

// formatRowDuration returns the display string for the DURATION column.
// While running it accumulates the in-flight elapsed time; otherwise it
// shows the total accumulated across completed turns. Empty when nothing
// has run yet.
func formatRowDuration(row agentRow) string {
	total := row.accumulated
	if !row.currentStart.IsZero() {
		total += time.Since(row.currentStart)
	}
	if total <= 0 {
		return ""
	}
	return formatDuration(total)
}

// formatDuration delegates to tuiutil.FormatDuration.
func formatDuration(d time.Duration) string {
	return tuiutil.FormatDuration(d)
}

// formatStance renders the APPROVED column from a canonical stance.
func formatStance(stance string) string {
	switch stance {
	case stanceApprove:
		return "✓ approve"
	case stanceRequestChanges:
		return "✗ changes"
	case stanceReject:
		return "✗ reject"
	default:
		return ""
	}
}

