package investigate

import (
	"fmt"
	"strings"
)

// entryLine renders one timelineEntry as a single display line truncated
// to maxWidth cells.
func entryLine(e timelineEntry, maxWidth int) string {
	var raw string
	switch e.kind {
	case "started":
		raw = fmt.Sprintf("[turn %d started %s]", e.turn, e.when.Format("15:04:05"))
	case "finished":
		parts := []string{fmt.Sprintf("[turn %d finished %s]", e.turn, formatDuration(e.duration))}
		if e.stance != "" {
			parts = append(parts, e.stance)
		}
		if e.findings != "" {
			parts = append(parts, fmt.Sprintf("%q", e.findings))
		}
		raw = strings.Join(parts, " · ")
	case "failed":
		parts := []string{fmt.Sprintf("[turn %d failed %s]", e.turn, formatDuration(e.duration))}
		if e.errStr != "" {
			parts = append(parts, e.errStr)
		}
		raw = strings.Join(parts, " · ")
	default:
		raw = fmt.Sprintf("[turn %d %s]", e.turn, e.kind)
	}
	return truncateDisplayWidth(sanitizeDisplayText(raw), maxWidth)
}

// detailView renders the alt-screen drill-in for one agent. The output
// is padded to exactly termHeight lines. termHeight and termWidth come
// from WindowSizeMsg via investigateTUIModel, so the rendered frame
// always fills the visible terminal.
func detailView(row agentRow, scroll, termWidth, termHeight int) string {
	if termWidth < 1 {
		termWidth = 80
	}
	if termHeight < 3 {
		termHeight = 3
	}
	bodyHeight := termHeight - 2

	headerContent := fmt.Sprintf("─── %s (%d turns) ", sanitizeDisplayText(row.name), len(row.buffer))
	header := padDisplayWidthWith(headerContent, termWidth, "─")

	lines := buildDetailBody(row.buffer, scroll, bodyHeight, termWidth)
	for len(lines) < bodyHeight {
		lines = append(lines, strings.Repeat(" ", termWidth))
	}

	footerText := "←/→ switch agent · ↑/↓ scroll · Esc back · Ctrl+C cancel"
	footer := padDisplayWidth(footerText, termWidth)

	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\n")
	for _, line := range lines {
		b.WriteString(line)
		b.WriteString("\n")
	}
	b.WriteString(footer)
	return b.String()
}

// buildDetailBody returns the visible body lines, clamped to bodyHeight.
// scroll is the index of the LAST visible entry; the body shows
// [scroll-bodyHeight+1 ... scroll] inclusive.
func buildDetailBody(buffer []timelineEntry, scroll, bodyHeight, termWidth int) []string {
	if len(buffer) == 0 || bodyHeight <= 0 {
		return nil
	}
	if scroll < 0 {
		scroll = 0
	}
	if scroll >= len(buffer) {
		scroll = len(buffer) - 1
	}
	end := scroll + 1
	start := end - bodyHeight
	if start < 0 {
		start = 0
	}
	lines := make([]string, 0, end-start)
	for i := start; i < end; i++ {
		lines = append(lines, entryLine(buffer[i], termWidth))
	}
	return lines
}

// Package investigate contains the env-var contract between `entire
// investigate` (which spawns the agent process) and the lifecycle hook (which
// adopts the session), plus the persisted run state for resuming an
// investigation. These names are stable API; renaming any constant is a
// breaking change.
//
// Design rationale: each spawned agent inherits its own copy of the process
// environment, so multi-tenant correctness (multiple worktrees, multi-agent
// runs) holds by construction — one agent's env vars cannot bleed into
// another agent's session. The lifecycle UserPromptSubmit hook reads these
// env vars to tag the in-flight session as an investigate session (Kind =
// "agent_investigate") and records the run id + topic.
package investigate

import (
	"github.com/entireio/cli/cmd/entire/cli/provenance"
)

// Investigate env vars. Names live in cmd/entire/cli/provenance; aliased
// here for the package's call sites.
const (
	EnvSession     = provenance.InvestigateSession
	EnvAgent       = provenance.InvestigateAgent
	EnvRunID       = provenance.InvestigateRunID
	EnvTopic       = provenance.InvestigateTopic
	EnvFindingsDoc = provenance.InvestigateFindingsDoc
	EnvStateDoc    = provenance.InvestigateStateDoc
	EnvStartingSHA = provenance.InvestigateStartingSHA
)

// AppendOptions carries the data needed to populate the ENTIRE_INVESTIGATE_*
// env vars on a spawned agent process.
type AppendOptions struct {
	AgentName   string
	RunID       string
	Topic       string
	FindingsDoc string
	StateDoc    string
	StartingSHA string
}

// AppendInvestigateEnv adds the ENTIRE_INVESTIGATE_* env vars to base,
// returning the new slice. Used by the loop driver when spawning each per-turn
// agent process to propagate the investigate-session contract.
//
// Any pre-existing ENTIRE_INVESTIGATE_* AND ENTIRE_REVIEW_* entries in base
// are stripped before the new values are appended. Stripping investigate
// entries handles nested invocations and stale inheritance from a parent
// shell — duplicate keys would otherwise have implementation-defined
// precedence. Stripping review entries prevents an outer `entire review`
// session from mis-tagging a child investigate session if invoked nested.
func AppendInvestigateEnv(base []string, opts AppendOptions) []string {
	out := make([]string, 0, len(base)+10)
	for _, kv := range base {
		if provenance.IsEntry(kv) {
			continue
		}
		out = append(out, kv)
	}
	return append(out,
		EnvSession+"=1",
		EnvAgent+"="+opts.AgentName,
		EnvRunID+"="+opts.RunID,
		EnvTopic+"="+opts.Topic,
		EnvFindingsDoc+"="+opts.FindingsDoc,
		EnvStateDoc+"="+opts.StateDoc,
		EnvStartingSHA+"="+opts.StartingSHA,
	)
}

// IsInvestigateEnvEntry reports whether kv is a "KEY=VALUE" entry whose key
// is one of the ENTIRE_INVESTIGATE_* contract variables.
func IsInvestigateEnvEntry(kv string) bool {
	return provenance.IsInvestigateEntry(kv)
}

// Package provenance owns the env-var contract that lets the lifecycle hook
// recognize a spawned agent process as part of `entire review` or `entire
// investigate`. Both spawn families set their own ENTIRE_*_* vars on the
// child agent process; the UserPromptSubmit hook reads them to tag the
// in-flight session with the right Kind and provenance metadata.
//
// Single source of truth for the names — review, investigate, and
// agentlaunch (which strips both families before spawning a fix agent) all
// reference this package.
//
// These names are stable API; renaming any constant is a breaking change.
package provenance

import "strings"

const (
	ReviewSession     = "ENTIRE_REVIEW_SESSION"
	ReviewAgent       = "ENTIRE_REVIEW_AGENT"
	ReviewSkills      = "ENTIRE_REVIEW_SKILLS"
	ReviewPrompt      = "ENTIRE_REVIEW_PROMPT"
	ReviewStartingSHA = "ENTIRE_REVIEW_STARTING_SHA"

	InvestigateSession     = "ENTIRE_INVESTIGATE_SESSION"
	InvestigateAgent       = "ENTIRE_INVESTIGATE_AGENT"
	InvestigateRunID       = "ENTIRE_INVESTIGATE_RUN_ID"
	InvestigateTopic       = "ENTIRE_INVESTIGATE_TOPIC"
	InvestigateFindingsDoc = "ENTIRE_INVESTIGATE_FINDINGS_DOC"
	InvestigateStateDoc    = "ENTIRE_INVESTIGATE_STATE_DOC"
	InvestigateStartingSHA = "ENTIRE_INVESTIGATE_STARTING_SHA"
)

var reviewPrefixes = []string{
	ReviewSession + "=",
	ReviewAgent + "=",
	ReviewSkills + "=",
	ReviewPrompt + "=",
	ReviewStartingSHA + "=",
}

var investigatePrefixes = []string{
	InvestigateSession + "=",
	InvestigateAgent + "=",
	InvestigateRunID + "=",
	InvestigateTopic + "=",
	InvestigateFindingsDoc + "=",
	InvestigateStateDoc + "=",
	InvestigateStartingSHA + "=",
}

// IsReviewEntry reports whether kv is a "KEY=VALUE" entry whose key is one
// of the ENTIRE_REVIEW_* contract variables.
func IsReviewEntry(kv string) bool {
	return hasAnyPrefix(kv, reviewPrefixes)
}

// IsInvestigateEntry reports whether kv is a "KEY=VALUE" entry whose key is
// one of the ENTIRE_INVESTIGATE_* contract variables.
func IsInvestigateEntry(kv string) bool {
	return hasAnyPrefix(kv, investigatePrefixes)
}

// IsEntry reports whether kv is a "KEY=VALUE" entry from either family.
// agentlaunch uses this to strip provenance markers before spawning a fix
// session so the child is not tagged as review or investigate.
func IsEntry(kv string) bool {
	return IsReviewEntry(kv) || IsInvestigateEntry(kv)
}

func hasAnyPrefix(s string, prefixes []string) bool {
	for _, p := range prefixes {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

// Package review contains the env-var contract between `entire review` (which
// spawns the agent process) and the lifecycle hook (which adopts the session).
// These names are stable API; renaming any constant is a breaking change.
//
// Design rationale: each spawned agent inherits its own copy of the process
// environment, so multi-tenant correctness (multiple worktrees, multi-agent
// runs) holds by construction — one agent's env vars cannot bleed into
// another agent's session. The lifecycle UserPromptSubmit hook reads these
// env vars to tag the in-flight session as a review session (Kind =
// "agent_review") and records which skills were run.
package review

import (
	"encoding/json"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/provenance"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// Review env vars. Names live in cmd/entire/cli/provenance; review aliases
// them so existing call sites (review.EnvSession, etc.) keep working.
const (
	EnvSession     = provenance.ReviewSession
	EnvAgent       = provenance.ReviewAgent
	EnvSkills      = provenance.ReviewSkills
	EnvPrompt      = provenance.ReviewPrompt
	EnvStartingSHA = provenance.ReviewStartingSHA
)

// EncodeSkills serialises a slice of skill invocation strings to a JSON value
// suitable for storing in the ENTIRE_REVIEW_SKILLS environment variable.
// An empty or nil slice encodes to the literal string "[]".
func EncodeSkills(skills []string) (string, error) {
	if len(skills) == 0 {
		return "[]", nil
	}
	b, err := json.Marshal(skills)
	if err != nil {
		return "", fmt.Errorf("encode skills: %w", err)
	}
	return string(b), nil
}

// DecodeSkills deserialises a value previously produced by EncodeSkills.
// An empty string decodes to a nil slice (no skills configured).
// Any other value that is not valid JSON returns an error.
func DecodeSkills(encoded string) ([]string, error) {
	if encoded == "" {
		return nil, nil
	}
	var skills []string
	if err := json.Unmarshal([]byte(encoded), &skills); err != nil {
		return nil, fmt.Errorf("decode skills: %w", err)
	}
	return skills, nil
}

// AppendReviewEnv adds the ENTIRE_REVIEW_* env vars to base, returning
// the new slice. Used by per-agent reviewers in their AgentReviewer.Start
// implementations to propagate the review-session contract to spawned
// agent processes.
//
// agentName must be the agent's stable registry key (e.g. "claude-code").
// cfg carries skills and the starting SHA. prompt is the full composed
// prompt text (result of ComposeReviewPrompt).
//
// Any pre-existing ENTIRE_REVIEW_* entries in base are stripped before the
// new values are appended. This handles nested invocations (an `entire
// review` run spawning another agent that calls `entire review`) and stale
// inheritance from a parent shell — the most-recent values must win, with
// no chance of duplicate keys whose precedence is implementation-defined.
func AppendReviewEnv(base []string, agentName string, cfg reviewtypes.RunConfig, prompt string) []string {
	skillsJSON, _ := EncodeSkills(cfg.Skills) //nolint:errcheck // EncodeSkills only fails on json.Marshal([]string), which is infallible
	out := make([]string, 0, len(base)+5)
	for _, kv := range base {
		if IsReviewEnvEntry(kv) {
			continue
		}
		out = append(out, kv)
	}
	return append(out,
		EnvSession+"=1",
		EnvAgent+"="+agentName,
		EnvSkills+"="+skillsJSON,
		EnvPrompt+"="+prompt,
		EnvStartingSHA+"="+cfg.StartingSHA,
	)
}

// IsReviewEnvEntry reports whether kv is a "KEY=VALUE" entry whose key is
// one of the ENTIRE_REVIEW_* contract variables. Exported for symmetry
// with investigate.IsInvestigateEnvEntry.
func IsReviewEnvEntry(kv string) bool {
	return provenance.IsReviewEntry(kv)
}

// Package agentlaunch is the shared "launch a normal coding agent session
// with a composed prompt" helper, used by `entire review --fix` and
// `entire investigate fix`. Both commands feed accepted findings back into
// a follow-up coding agent without spawning a review/investigate session
// themselves.
//
// The package is a leaf so review and investigate (which depend on it)
// avoid an import cycle. The env-var names it strips live in
// cmd/entire/cli/provenance (also a leaf).
package agentlaunch

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	agenttypes "github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/provenance"
)

// LaunchFixAgent starts a normal coding agent session with the given
// prompt. ENTIRE_REVIEW_* and ENTIRE_INVESTIGATE_* env entries are stripped
// from the child process so the fix session is not tagged as a review or
// investigate.
//
// agentName must be a launchable agent registry name. Returns nil on clean
// exit, or a wrapped error on cancellation / non-zero exit. Output / input
// are connected to the calling process's stdio so the user can interact
// with the fix session in their terminal.
func LaunchFixAgent(ctx context.Context, agentName string, prompt string) error {
	ag, err := agent.Get(agenttypes.AgentName(agentName))
	if err != nil {
		return fmt.Errorf("resolve fix agent %s: %w", agentName, err)
	}
	launcher, ok := agent.LauncherFor(ag.Name())
	if !ok {
		return fmt.Errorf("agent %s cannot be launched for fix sessions", agentName)
	}
	cmd, err := launcher.LaunchCmd(ctx, prompt)
	if err != nil {
		return fmt.Errorf("build fix command: %w", err)
	}
	cmd.Env = withoutReviewOrInvestigateEnv(cmd.Env)
	if len(cmd.Env) == 0 {
		cmd.Env = withoutReviewOrInvestigateEnv(os.Environ())
	}
	if err := cmd.Run(); err != nil {
		if errors.Is(err, context.Canceled) {
			return fmt.Errorf("fix agent cancelled: %w", err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return fmt.Errorf("fix agent exited with status %d: %w", exitErr.ExitCode(), err)
		}
		return fmt.Errorf("run fix agent: %w", err)
	}
	return nil
}

// withoutReviewOrInvestigateEnv returns a copy of base with all
// ENTIRE_REVIEW_* and ENTIRE_INVESTIGATE_* entries removed. The returned
// slice is fresh — base is never mutated.
func withoutReviewOrInvestigateEnv(base []string) []string {
	out := make([]string, 0, len(base))
	for _, kv := range base {
		if provenance.IsEntry(kv) {
			continue
		}
		out = append(out, kv)
	}
	return out
}

