// RunShow prints the saved investigation summary + findings for the
// requested run id. Resolution rules:
//   - empty RunID + exactly one manifest → use that manifest
//   - empty RunID + multiple manifests   → list candidates, return error
//   - non-empty RunID: exact match wins; otherwise unique-prefix match;
//     otherwise return an "ambiguous" or "not found" error
//
// Findings come from manifest.FindingsContent when present (terminal
// outcomes), or by reading manifest.FindingsDoc from disk (paused /
// cancelled runs whose per-run dir still exists). Both paths missing
// is a soft state — the header is printed with an explanatory line.
func RunShow(ctx context.Context, in ShowInput, deps ShowDeps) error {
	if deps.ManifestStore == nil {
		return errors.New("show: manifest store not wired")
	}

	// Fast path: a full 12-hex run id resolves via Glob + one file read.
	runID := strings.TrimSpace(in.RunID)
	if IsValidRunID(runID) {
		m, ok, err := deps.ManifestStore.FindByRunID(ctx, runID)
		if err != nil {
			return fmt.Errorf("find manifest %s: %w", runID, err)
		}
		if !ok {
			return fmt.Errorf("no investigation found with run id %q", runID)
		}
		printShowSummary(in.Out, m)
		printShowFindings(in.Out, m)
		return nil
	}

	manifests, err := deps.ManifestStore.List(ctx)
	if err != nil {
		return fmt.Errorf("list manifests: %w", err)
	}
	if len(manifests) == 0 {
		fmt.Fprintln(in.Out, "No local investigations found.")
		return nil
	}

	if runID == "" {
		if len(manifests) == 1 {
			printShowSummary(in.Out, manifests[0])
			printShowFindings(in.Out, manifests[0])
			return nil
		}
		return ambiguousRunIDError(manifests, "")
	}

	resolved, err := ResolveByRunID(manifests, runID)
	if err != nil {
		return err
	}
	printShowSummary(in.Out, resolved[0])
	printShowFindings(in.Out, resolved[0])
	return nil
}

// printShowSummary writes the header block (prompt, agents, outcome,
// timestamps, stances per agent) to w. Keeps the format compact and
// stable so users can grep its output.
func printShowSummary(w io.Writer, m LocalManifest) {
	fmt.Fprintf(w, "Investigation %s\n", m.RunID)
	if m.Topic != "" {
		fmt.Fprintf(w, "Prompt:   %s\n", m.Topic)
	}
	if len(m.Agents) > 0 {
		fmt.Fprintf(w, "Agents:   %s\n", strings.Join(m.Agents, ", "))
	}
	if m.Outcome != "" {
		fmt.Fprintf(w, "Outcome:  %s\n", m.Outcome)
	}
	if !m.StartedAt.IsZero() {
		fmt.Fprintf(w, "Started:  %s\n", m.StartedAt.UTC().Format("2006-01-02 15:04:05Z"))
	}
	if !m.EndedAt.IsZero() {
		fmt.Fprintf(w, "Ended:    %s\n", m.EndedAt.UTC().Format("2006-01-02 15:04:05Z"))
	}
	if len(m.StancesByAgent) > 0 {
		keys := make([]string, 0, len(m.StancesByAgent))
		for k := range m.StancesByAgent {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Last stance per agent:")
		for _, k := range keys {
			fmt.Fprintf(w, "  %s: %s\n", k, m.StancesByAgent[k])
		}
	}
	fmt.Fprintln(w)
}

// printShowFindings writes the findings content to w. Prefers the
// manifest's embedded content (set on terminal outcomes); falls back
// to reading the on-disk findings file (still present for paused or
// cancelled runs). Body is rendered through mdrender for terminal
// output; raw markdown passes through for piped/NO_COLOR output.
func printShowFindings(w io.Writer, m LocalManifest) {
	body := ""
	switch {
	case m.FindingsContent != "":
		body = m.FindingsContent
	case m.FindingsDoc != "":
		if data, err := os.ReadFile(m.FindingsDoc); err == nil {
			body = string(data)
		}
	}
	if body == "" {
		fmt.Fprintf(w, "No findings content available for run %s.\n", m.RunID)
		return
	}
	rendered, err := mdrender.RenderForWriter(w, body)
	if err != nil {
		// Glamour failure: fall back to raw markdown so the user still
		// sees the content.
		rendered = body
	}
	fmt.Fprint(w, rendered)
	if !strings.HasSuffix(rendered, "\n") {
		fmt.Fprintln(w)
	}
}

package investigate

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
)

// defaultFixAgent is the agent registry name used when FixDeps.FixAgent is
// empty.
//
// TODO: layer on `entire investigate fix --agent <name>` and a settings
// override.
const defaultFixAgent = "claude-code"

// FixDeps collects what RunFix needs that's injectable for tests.
type FixDeps struct {
	// ManifestStore loads local manifests by run ID.
	ManifestStore *LocalManifestStore

	// FixAgent is the agent registry name to launch. When empty, RunFix
	// falls back to defaultFixAgent.
	FixAgent string

	// Launch runs the actual coding agent session. Production wires this
	// to agentlaunch.LaunchFixAgent.
	Launch func(ctx context.Context, agentName string, prompt string) error

	// ReadFile, when non-nil, replaces os.ReadFile.
	ReadFile func(name string) ([]byte, error)
}

// FixInput drives RunFix.
type FixInput struct {
	// RunID resolves a specific run; empty means "pick the most recent".
	RunID string

	// Out is the user-facing stream for the launch banner.
	Out io.Writer

	// ErrOut is the user-facing stream for warnings (e.g. missing doc).
	ErrOut io.Writer
}

// RunFix resolves a saved investigation, composes the follow-up prompt,
// and launches a coding agent session via deps.Launch.
//
// The prompt body says "use these findings as grounded context, do not
// re-investigate". The composed prompt embeds the findings doc verbatim
// so the agent has full access without needing to re-read disk.
func RunFix(ctx context.Context, in FixInput, deps FixDeps) error {
	if deps.ManifestStore == nil {
		return errors.New("fix: manifest store is required")
	}
	if deps.Launch == nil {
		return errors.New("fix: launch function is required")
	}

	manifest, err := resolveFixManifest(ctx, deps.ManifestStore, in.RunID)
	if err != nil {
		return err
	}

	readFile := deps.ReadFile
	if readFile == nil {
		readFile = os.ReadFile
	}

	// Prefer the manifest's embedded findings content (populated on
	// terminal outcomes — the per-run dir is auto-cleaned, so FindingsDoc
	// points at a deleted path). Fall back to reading the on-disk file
	// for paused/cancelled runs where the dir is preserved.
	findingsBody := manifest.FindingsContent
	if findingsBody == "" {
		findingsBody = readDocOrWarn(readFile, manifest.FindingsDoc, "findings", in.ErrOut)
	}

	prompt := composeFixPrompt(manifest, findingsBody)

	fixAgent := deps.FixAgent
	if fixAgent == "" {
		fixAgent = defaultFixAgent
	}

	if in.Out != nil {
		fmt.Fprintf(in.Out, "Launching %s with findings from run %s ...\n", fixAgent, manifest.RunID)
	}

	return deps.Launch(ctx, fixAgent, prompt)
}

// resolveFixManifest picks the manifest to feed the fix agent. Empty
// runID means "use the most recent run"; a specific runID requires an
// exact match.
func resolveFixManifest(ctx context.Context, store *LocalManifestStore, runID string) (LocalManifest, error) {
	if runID != "" {
		manifest, ok, err := store.FindByRunID(ctx, runID)
		if err != nil {
			return LocalManifest{}, err
		}
		if !ok {
			return LocalManifest{}, fmt.Errorf("no investigation found with run id %q", runID)
		}
		return manifest, nil
	}
	m, ok, err := store.Latest(ctx)
	if err != nil {
		return LocalManifest{}, err
	}
	if !ok {
		return LocalManifest{}, errors.New("no local investigations found")
	}
	return m, nil
}

// readDocOrWarn reads path with the supplied reader. A missing or
// unreadable path yields an empty string and a warning to errOut (when
// non-nil); the caller is expected to handle empty doc bodies gracefully
// in the composed prompt. An empty path yields "" without a warning,
// since the manifest legitimately may not record both documents.
func readDocOrWarn(read func(string) ([]byte, error), path string, label string, errOut io.Writer) string {
	if path == "" {
		return ""
	}
	b, err := read(path)
	if err != nil {
		if errOut != nil {
			fmt.Fprintf(errOut, "warning: could not read %s doc %q: %v\n", label, path, err)
		}
		return ""
	}
	return string(b)
}

// composeFixPrompt builds the follow-up prompt sent to the fix agent: a
// "do not re-investigate" preamble, the run identity, and the findings
// body verbatim under a section heading. An empty findings body is still
// emitted with a placeholder line so the agent sees the section
// structure consistently.
func composeFixPrompt(manifest LocalManifest, findings string) string {
	var b strings.Builder
	b.WriteString("A prior multi-agent investigation produced these findings. Use them as\n")
	b.WriteString("grounded context to plan the next step. Do not re-investigate the same\n")
	b.WriteString("question — assume the findings are correct unless you find direct\n")
	b.WriteString("evidence to the contrary.\n\n")
	if prompt := strings.TrimSpace(manifest.Topic); prompt != "" {
		fmt.Fprintf(&b, "Investigation: %s\n", prompt)
	}
	if manifest.RunID != "" {
		fmt.Fprintf(&b, "Run ID: %s\n", manifest.RunID)
	}
	b.WriteString("\n## Investigation findings\n\n")
	if body := strings.TrimSpace(findings); body != "" {
		b.WriteString(body)
		b.WriteString("\n")
	} else {
		b.WriteString("(no findings recorded)\n")
	}
	return b.String()
}

