13	// fixLaunchRecord captures the (agentName, prompt) pair Launch was called
14	// with so the test can assert what RunFix forwarded to the launcher.
15	type fixLaunchRecord struct {
16		called    bool
17		agentName string
18		prompt    string
19	}
20	
21	// stubLaunch returns a Launch function that records its arguments into
22	// rec. The returned function always reports success; tests that need a
23	// failing launch can substitute their own closure.
24	func stubLaunch(rec *fixLaunchRecord) func(context.Context, string, string) error {
25		return func(_ context.Context, agentName, prompt string) error {
26			rec.called = true
27			rec.agentName = agentName
28			rec.prompt = prompt
29			return nil
30		}
31	}
32	
33	// writeFixManifest is a shorthand for tests: build a manifest with the
34	// supplied identity and persist it to store. RunID/Topic/StartedAt are
35	// the discriminators tests care about; the rest is filled with sensible
36	// defaults so the manifest passes Write validation.
37	func writeFixManifest(t *testing.T, store *LocalManifestStore, runID, topic string, started time.Time, findingsDoc string) {
38		t.Helper()
39		m := LocalManifest{
40			RunID:       runID,
41			Topic:       topic,
42			Slug:        SlugifyTopic(topic),
43			StartingSHA: "deadbeefcafe",
44			FindingsDoc: findingsDoc,
45			Agents:      []string{"claude-code", "codex"},
46			Outcome:     "quorum",
47			StartedAt:   started,
48			EndedAt:     started.Add(10 * time.Minute),
49		}
50		if err := store.Write(context.Background(), m); err != nil {
51			t.Fatalf("Write %s: %v", runID, err)
52		}
53	}
