				"ENTIRE_REVIEW_AGENT=claude-code",
				"ENTIRE_REVIEW_SKILLS=[\"/x\"]",
				"ENTIRE_REVIEW_PROMPT=stale review prompt",
				"ENTIRE_REVIEW_STARTING_SHA=stale1",
				"ENTIRE_INVESTIGATE_SESSION=1",
