			},
			want: []string{
				"NOT_ENTIRE_REVIEW_SESSION=1",
				"ENTIRE_REVIEW_OTHER=keep",
				"ENTIRE_INVESTIGATE_OTHER=keep",
			},
			wantSize: 3,
		},
	}

