// are filtered out at the SpawnerFor check.
func RunInvestigateConfigPicker(
	ctx context.Context,
	out io.Writer,
	spawnerFor func(agentName string) spawn.Spawner,
	getAgentsWithHooksInstalled func(ctx context.Context) []types.AgentName,
