12		"github.com/entireio/cli/cmd/entire/cli/paths"
13		"github.com/entireio/cli/cmd/entire/cli/settings"
14	
15		git "github.com/go-git/go-git/v6"
16		"github.com/go-git/go-git/v6/plumbing"
17	)
18	
19	// CommittedReader provides read access to committed checkpoint data.
20	// Both GitStore (v1) and V2GitStore (v2) implement this interface.
21	type CommittedReader interface {
22		ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
23		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
24	}
25	
26	// CommittedListReader provides read and list access to committed checkpoint data.
27	// GitStore, V2GitStore, and DualCheckpointReader implement this interface.
28	type CommittedListReader interface {
29		CommittedReader
30		ListCommitted(ctx context.Context) ([]CommittedInfo, error)
31		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error)
32		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
33		ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error)
34	}
35	
36	// CommittedStore provides read/list access plus committed checkpoint metadata updates.
37	// NewCommittedReader returns this abstraction so callers do not need to know which
38	// backing checkpoint format was selected.
39	type CommittedStore interface {
40		CommittedListReader
41		UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error
42		GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error)
43	}
44	
45	type committedReadMode int
46	
47	const (
48		committedReadV1 committedReadMode = iota
49		committedReadDual
50		committedReadV2
51	)
52	
53	// CommittedReaderOptions configures NewCommittedReader.
54	type CommittedReaderOptions struct {
55		BlobFetcher BlobFetchFunc
56	}
57	
58	func NewCommittedReader(ctx context.Context, repo *git.Repository, opts CommittedReaderOptions) (CommittedStore, error) { //nolint:ireturn // Factory selects among v1, v2, and dual reader implementations.
59		if repo == nil {
60			return nil, errors.New("git repository is required")
61		}
62	
63		v1Store := NewGitStore(repo)
64		if opts.BlobFetcher != nil {
65			v1Store.SetBlobFetcher(opts.BlobFetcher)
66		}
67	
68		v2Enabled := settings.IsCheckpointsV2Enabled(ctx)
69		version := settings.CheckpointsVersion(ctx)
70		localV2MainRef := false
71		if version != 2 && !v2Enabled {
72			localV2MainRef = hasLocalV2MainRef(repo)
73		}
74		mode := resolveCommittedReadMode(v2Enabled, version, localV2MainRef)
75	
76		var v2Store *V2GitStore
77		if mode != committedReadV1 {
78			v2Store = NewV2GitStore(repo)
79			if opts.BlobFetcher != nil {
80				v2Store.SetBlobFetcher(opts.BlobFetcher)
81			}
82		}
83	
84		switch mode {
85		case committedReadV2:
86			return v2Store, nil
87		case committedReadDual:
88			return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
89		case committedReadV1:
90			return v1Store, nil
91		default:
92			return nil, fmt.Errorf("unknown committed checkpoint read mode: %d", mode)
93		}
94	}
95	
96	func resolveCommittedReadMode(checkpointsV2Enabled bool, checkpointsVersion int, localV2MainRef bool) committedReadMode {
97		if checkpointsVersion == 2 {
98			return committedReadV2
99		}
100		if checkpointsV2Enabled || localV2MainRef {
101			return committedReadDual
102		}
103		return committedReadV1
104	}
105	
106	func hasLocalV2MainRef(repo *git.Repository) bool {
107		if repo == nil {
108			return false
109		}
110		_, err := repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
111		return err == nil
112	}
113	
114	type DualCheckpointReader struct {
115		v2 *V2GitStore
116		v1 *GitStore
117	}
118	
119	func (r *DualCheckpointReader) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
120		summary, err := r.v2.ReadCommitted(ctx, checkpointID)
121		if err == nil && summary != nil {
122			return summary, nil
123		}
124		if ctxErr := ctx.Err(); ctxErr != nil {
125			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
126		}
127		if err != nil {
128			logV2Fallback(ctx, "v2 ReadCommitted failed, falling back to v1", checkpointID, err)
129		}
130		return r.v1.ReadCommitted(ctx, checkpointID)
131	}
132	
133	func (r *DualCheckpointReader) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
134		content, err := r.v2.ReadSessionContent(ctx, checkpointID, sessionIndex)
135		if err == nil {
136			return content, nil
137		}
138		if ctxErr := ctx.Err(); ctxErr != nil {
139			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
140		}
141		if errors.Is(err, ErrCheckpointNotFound) {
142			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
143			if existsErr != nil {
144				return nil, existsErr
145			}
146			if v2CheckpointExists {
147				summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
148				if summaryErr != nil {
149					return nil, summaryErr
150				}
151				if !hasSingleV1FallbackSession(summary, sessionIndex) {
152					return nil, err
153				}
154				return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
155			}
156			return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
157		}
158		sessionID, sessionIDErr := r.v2SessionID(ctx, checkpointID, sessionIndex)
159		if sessionIDErr != nil {
160			if ctxErr := ctx.Err(); ctxErr != nil {
161				return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
162			}
163			originalErr := fallbackReadError(err, "read v2 session metadata for v1 fallback", sessionIDErr)
164			summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, originalErr)
165			if summaryErr != nil {
166				return nil, summaryErr
167			}
168			if !hasSingleV1FallbackSession(summary, sessionIndex) {
169				return nil, originalErr
170			}
171			return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, originalErr)
172		}
173		return r.readV1SessionContentByID(ctx, checkpointID, sessionID, err)
174	}
175	
176	func (r *DualCheckpointReader) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error) {
177		metadata, err := r.v2.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
178		if err == nil {
179			return metadata, nil
180		}
181		if ctxErr := ctx.Err(); ctxErr != nil {
182			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
183		}
184		if errors.Is(err, ErrCheckpointNotFound) {
185			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
186			if existsErr != nil {
187				return nil, existsErr
188			}
189			if v2CheckpointExists {
190				summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
191				if summaryErr != nil {
192					return nil, summaryErr
193				}
194				if !hasSingleV1FallbackSession(summary, sessionIndex) {
195					return nil, err
196				}
197				return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
198			}
199			return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
200		}
201		summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
202		if summaryErr != nil {
203			return nil, summaryErr
204		}
205		if !hasSingleV1FallbackSession(summary, sessionIndex) {
206			return nil, err
207		}
208		return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
209	}
210	
211	func (r *DualCheckpointReader) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
212		content, err := r.v2.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
213		if err == nil {
214			if content != nil && content.Prompts == "" && content.Metadata.SessionID != "" {
215				v1Content, fallbackErr := r.readV1SessionMetadataAndPromptsByID(ctx, checkpointID, content.Metadata.SessionID, ErrCheckpointNotFound)
216				if fallbackErr == nil {
217					content.Prompts = v1Content.Prompts
218				}
219				if ctxErr := ctx.Err(); ctxErr != nil {
220					return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
221				}
222			}
223			return content, nil
224		}
225		if ctxErr := ctx.Err(); ctxErr != nil {
226			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
227		}
228		if errors.Is(err, ErrCheckpointNotFound) {
229			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
230			if existsErr != nil {
231				return nil, existsErr
232			}
233			if v2CheckpointExists {
234				return nil, err
235			}
236			return r.readV1SessionMetadataAndPromptsByIndex(ctx, checkpointID, sessionIndex, err)
237		}
238		sessionID, sessionIDErr := r.v2SessionID(ctx, checkpointID, sessionIndex)
239		if sessionIDErr != nil {
240			if ctxErr := ctx.Err(); ctxErr != nil {
241				return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
242			}
243			originalErr := fallbackReadError(err, "read v2 session metadata for v1 fallback", sessionIDErr)
244			summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, originalErr)
245			if summaryErr != nil {
246				return nil, summaryErr
247			}
248			if !hasSingleV1FallbackSession(summary, sessionIndex) {
249				return nil, originalErr
250			}
251			return r.readV1SessionMetadataAndPromptsByIndex(ctx, checkpointID, sessionIndex, originalErr)
252		}
253		return r.readV1SessionMetadataAndPromptsByID(ctx, checkpointID, sessionID, err)
254	}
255	
256	func (r *DualCheckpointReader) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
257		prompts, err := r.v2.ReadSessionPrompts(ctx, checkpointID, sessionIndex)
258		if err == nil {
259			if prompts == "" {
260				v1Prompts, fallbackErr := r.v1.ReadSessionPrompts(ctx, checkpointID, sessionIndex)
261				if fallbackErr == nil {
262					return v1Prompts, nil
263				}
264				if ctxErr := ctx.Err(); ctxErr != nil {
265					return "", ctxErr //nolint:wrapcheck // Propagating context cancellation
266				}
267			}
268			return prompts, nil
269		}
270		if ctxErr := ctx.Err(); ctxErr != nil {
271			return "", ctxErr //nolint:wrapcheck // Propagating context cancellation
272		}
273		if errors.Is(err, ErrCheckpointNotFound) {
274			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
275			if existsErr != nil {
276				return "", existsErr
277			}
278			if v2CheckpointExists {
279				return "", err
280			}
281		}
282		prompts, fallbackErr := r.v1.ReadSessionPrompts(ctx, checkpointID, sessionIndex)
283		if fallbackErr == nil {
284			return prompts, nil
285		}
286		if ctxErr := ctx.Err(); ctxErr != nil {
287			return "", ctxErr //nolint:wrapcheck // Propagating context cancellation
288		}
289		return "", fallbackReadError(err, "read v1 session prompts", fallbackErr)
290	}
291	
292	func (r *DualCheckpointReader) ReadSessionCompactTranscript(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
293		return r.v2.ReadSessionCompactTranscript(ctx, checkpointID, sessionIndex)
294	}
295	
296	func (r *DualCheckpointReader) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
297		v2Committed, v2Err := r.v2.ListCommitted(ctx)
298		v1Committed, v1Err := r.v1.ListCommitted(ctx)
299	
300		if v2Err != nil {
301			logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
302				slog.String("error", v2Err.Error()),
303			)
304			if v1Err != nil {
305				return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
306			}
307			return v1Committed, nil
308		}
309	
310		if v1Err != nil {
311			logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
312				slog.String("error", v1Err.Error()),
313			)
314			return v2Committed, nil
315		}
316	
317		seen := make(map[id.CheckpointID]struct{}, len(v2Committed))
318		for _, c := range v2Committed {
319			seen[c.CheckpointID] = struct{}{}
320		}
321		committed := make([]CommittedInfo, 0, len(v2Committed)+len(v1Committed))
322		committed = append(committed, v2Committed...)
323		for _, c := range v1Committed {
324			if _, ok := seen[c.CheckpointID]; !ok {
325				committed = append(committed, c)
326			}
327		}
328		slices.SortFunc(committed, func(a, b CommittedInfo) int {
329			return b.CreatedAt.Compare(a.CreatedAt)
330		})
331		return committed, nil
332	}
333	
334	func (r *DualCheckpointReader) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
335		err := r.v2.UpdateSummary(ctx, checkpointID, summary)
336		if err == nil {
337			return nil
338		}
339		if ctxErr := ctx.Err(); ctxErr != nil {
340			return ctxErr //nolint:wrapcheck // Propagating context cancellation
341		}
342		if !errors.Is(err, ErrCheckpointNotFound) {
343			return fmt.Errorf("update v2 checkpoint summary: %w", err)
344		}
345		fallbackErr := r.v1.UpdateSummary(ctx, checkpointID, summary)
346		if fallbackErr == nil {
347			return nil
348		}
349		return fallbackReadError(err, "update v1 checkpoint summary", fallbackErr)
350	}
351	
352	func (r *DualCheckpointReader) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
353		author, err := r.v2.GetCheckpointAuthor(ctx, checkpointID)
354		if err == nil && (author.Name != "" || author.Email != "") {
355			return author, nil
356		}
357		if ctxErr := ctx.Err(); ctxErr != nil {
358			return Author{}, ctxErr //nolint:wrapcheck // Propagating context cancellation
359		}
360		v1Author, v1Err := r.v1.GetCheckpointAuthor(ctx, checkpointID)
361		if v1Err == nil {
362			return v1Author, nil
363		}
364		return Author{}, fallbackReadError(err, "read v1 checkpoint author", v1Err)
365	}
366	
367	func (r *DualCheckpointReader) v2CheckpointExists(ctx context.Context, checkpointID id.CheckpointID) (bool, error) {
368		if err := ctx.Err(); err != nil {
369			return false, err //nolint:wrapcheck // Propagating context cancellation
370		}
371		checkpointExists := false
372		_, rootTreeHash, err := r.v2.GetRefState(plumbing.ReferenceName(paths.V2MainRefName))
373		if err == nil {
374			rootTree, err := r.v2.repo.TreeObject(rootTreeHash)
375			if err == nil {
376				_, err = rootTree.Tree(checkpointID.Path())
377				checkpointExists = err == nil
378			}
379		}
380		return checkpointExists, nil
381	}
382	
383	func (r *DualCheckpointReader) v2SessionID(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
384		metadata, err := r.v2.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
385		if err != nil {
386			return "", err
387		}
388		if metadata == nil || metadata.SessionID == "" {
389			return "", ErrNoTranscript
390		}
391		return metadata.SessionID, nil
392	}
393	
394	func (r *DualCheckpointReader) readV1SessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string, originalErr error) (*SessionContent, error) {
395		content, fallbackErr := r.v1.ReadSessionContentByID(ctx, checkpointID, sessionID)
396		if fallbackErr == nil {
397			return content, nil
398		}
399		if ctxErr := ctx.Err(); ctxErr != nil {
400			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
401		}
402		return nil, fallbackReadError(originalErr, "read v1 fallback session content", fallbackErr)
403	}
404	
405	func (r *DualCheckpointReader) readV1SessionContentByIndex(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, originalErr error) (*SessionContent, error) {
406		content, err := r.v1.ReadSessionContent(ctx, checkpointID, sessionIndex)
407		if err == nil {
408			return content, nil
409		}
410		if ctxErr := ctx.Err(); ctxErr != nil {
411			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
412		}
413		return nil, fallbackReadError(originalErr, "read v1 session content", err)
414	}
415	
416	func (r *DualCheckpointReader) readV1SessionMetadataByIndex(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, originalErr error) (*CommittedMetadata, error) {
417		metadata, err := r.v1.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
418		if err == nil {
419			return metadata, nil
420		}
421		if ctxErr := ctx.Err(); ctxErr != nil {
422			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
423		}
424		return nil, fallbackReadError(originalErr, "read v1 session metadata", err)
425	}
426	
427	func (r *DualCheckpointReader) readV1SessionMetadataAndPromptsByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string, originalErr error) (*SessionContent, error) {
428		summary, err := r.readV1FallbackSummary(ctx, checkpointID, originalErr)
429		if err != nil {
430			return nil, err
431		}
432		if summary == nil {
433			return nil, originalErr
434		}
435		for i := range len(summary.Sessions) {
436			metadata, readErr := r.v1.ReadSessionMetadata(ctx, checkpointID, i)
437			if readErr != nil {
438				continue
439			}
440			if metadata == nil || metadata.SessionID != sessionID {
441				continue
442			}
443			prompts, promptsErr := r.v1.ReadSessionPrompts(ctx, checkpointID, i)
444			if promptsErr != nil {
445				return nil, fallbackReadError(originalErr, "read v1 fallback session prompts", promptsErr)
446			}
447			return &SessionContent{Metadata: *metadata, Prompts: prompts}, nil
448		}
449		return nil, fallbackReadError(originalErr, "read v1 fallback session metadata and prompts", fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID))
450	}
451	
452	func (r *DualCheckpointReader) readV1SessionMetadataAndPromptsByIndex(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, originalErr error) (*SessionContent, error) {
453		content, err := r.v1.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
454		if err == nil {
455			return content, nil
456		}
457		if ctxErr := ctx.Err(); ctxErr != nil {
458			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
459		}
460		return nil, fallbackReadError(originalErr, "read v1 session metadata and prompts", err)
461	}
462	
463	func (r *DualCheckpointReader) readV1FallbackSummary(ctx context.Context, checkpointID id.CheckpointID, originalErr error) (*CheckpointSummary, error) {
464		summary, err := r.v1.ReadCommitted(ctx, checkpointID)
465		if err == nil {
466			return summary, nil
467		}
468		if ctxErr := ctx.Err(); ctxErr != nil {
469			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
470		}
471		return nil, fallbackReadError(originalErr, "read v1 checkpoint summary", err)
472	}
473	
474	func hasSingleV1FallbackSession(summary *CheckpointSummary, sessionIndex int) bool {
475		return summary != nil && len(summary.Sessions) == 1 && sessionIndex == 0
476	}
477	
478	func fallbackReadError(primaryErr error, fallbackOperation string, fallbackErr error) error {
479		if fallbackErr == nil {
480			return primaryErr
481		}
482		return errors.Join(primaryErr, fmt.Errorf("%s: %w", fallbackOperation, fallbackErr))
483	}
484	
485	func logV2Fallback(ctx context.Context, message string, checkpointID id.CheckpointID, err error) {
486		if errors.Is(err, ErrCheckpointNotFound) || errors.Is(err, ErrNoTranscript) {
487			return
488		}
489		logging.Debug(ctx, message,
490			slog.String("checkpoint_id", checkpointID.String()),
491			slog.String("error", err.Error()),
492		)
493	}
494	
495	// ReadCommittedCheckpoint reads a committed checkpoint summary and normalizes
496	// a nil store response into ErrCheckpointNotFound.
497	func ReadCommittedCheckpoint(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
498		if err := ctx.Err(); err != nil {
499			return nil, err //nolint:wrapcheck // Propagating context cancellation
500		}
501	
502		summary, err := reader.ReadCommitted(ctx, checkpointID)
503		if err != nil {
504			return nil, fmt.Errorf("read committed checkpoint: %w", err)
505		}
506		if summary == nil {
507			return nil, ErrCheckpointNotFound
508		}
509		return summary, nil
510	}
511	
512	// ReadLatestSessionContent reads the latest session from an already-resolved
513	// committed reader and summary.
514	func ReadLatestSessionContent(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
515		if summary == nil || len(summary.Sessions) == 0 {
516			return nil, ErrCheckpointNotFound
517		}
518		latestIndex := len(summary.Sessions) - 1
519		content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
520		if err != nil {
521			return nil, fmt.Errorf("read session %d content: %w", latestIndex, err)
522		}
523		return content, nil
524	}
525	
526	func ReadRawSessionLogForCheckpoint(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID) ([]byte, string, error) {
527		if err := ctx.Err(); err != nil {
528			return nil, "", err //nolint:wrapcheck // Propagating context cancellation
529		}
530	
531		summary, err := ReadCommittedCheckpoint(ctx, reader, checkpointID)
532		if err != nil {
533			return nil, "", err
534		}
535	
536		content, err := ReadLatestSessionContent(ctx, reader, checkpointID, summary)
537		if err != nil {
538			return nil, "", err
539		}
540		return content.Transcript, content.Metadata.SessionID, nil
541	}
